window.AtlasChapters=(window.AtlasChapters||[]).concat([{"id":81,"title":"81단계 — be allowed to / let","html":"\u003ch1 id=\"lesson-title\" data-id=\"81\">81단계 — be allowed to / let\u003c/h1>\n\u003cp>이번에는 \u003cstrong>허락\u003c/strong>을 표현하는 두 구조를 배운다.\u003c/p>\n\u003cp>핵심:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be allowed to + 동사원형\u003c/strong> = ~해도 된다 / ~하도록 허락받다\u003cbr>\u003cstrong>let + 사람 + 동사원형\u003c/strong> = 누구에게 ~하게 해주다\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>be allowed to\u003c/code>\u003c/h2>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~하는 것이 허용되어 있다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>We \u003cstrong>are allowed to use\u003c/strong> this room.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>우리는 이 방을 사용해도 된다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be동사 + allowed to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 주어에 따라 be동사 변화\u003c/h2>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">현재\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am allowed to\u003c/strong> go.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>is allowed to\u003c/strong> go.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They \u003cstrong>are allowed to\u003c/strong> go.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>am/is/are + allowed to + 동사원형\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">3. 규칙상 허용\u003c/h2>\n\u003cblockquote>\n\u003cp>You are allowed to park here.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>여기 주차해도 된다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 문장은:\u003c/p>\n\u003cblockquote>\n\u003cp>누군가가 허락해주었다\u003c/p>\n\u003c/blockquote>\n\u003cp>보다는\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>규칙상 허용되어 있다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 느낌으로도 자주 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">4. 부정형\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>be not allowed to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~하면 안 된다 / ~하는 것이 허용되지 않는다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>You \u003cstrong>are not allowed to smoke\u003c/strong> here.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>여기서는 담배를 피우면 안 된다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Children \u003cstrong>aren&#39;t allowed to enter\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>아이들은 들어갈 수 없다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">5. \u003ccode>can\u003c/code>과 비교\u003c/h2>\n\u003cp>둘 다 허락을 나타낼 수 있다.\u003c/p>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">can\u003c/h3>\n\u003cblockquote>\n\u003cp>You \u003cstrong>can use\u003c/strong> my phone.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내 휴대폰 써도 돼.\u003c/p>\n\u003c/blockquote>\n\u003cp>일상적인 허락.\u003c/p>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">be allowed to\u003c/h3>\n\u003cblockquote>\n\u003cp>You \u003cstrong>are allowed to use\u003c/strong> this equipment.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이 장비는 사용이 허용되어 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>조금 더 \u003cstrong>공식적·규칙적인 허가\u003c/strong>에 잘 어울린다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">6. 과거 허락\u003c/h2>\n\u003cp>\u003ccode>can\u003c/code>만으로 과거의 모든 허락을 표현하기는 어렵다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>was/were allowed to\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 쓴다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>We \u003cstrong>were allowed to leave\u003c/strong> early.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>우리는 일찍 퇴근해도 된다는 허락을 받았다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">7. 미래 허락\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>will be allowed to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>You \u003cstrong>will be allowed to enter\u003c/strong> after 9.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>9시 이후에는 들어갈 수 있게 될 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>be allowed to\u003c/code>는 이렇게 시제를 자유롭게 바꿀 수 있다는 장점이 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">8. \u003ccode>let + 사람 + 동사원형\u003c/code>\u003c/h2>\n\u003cp>앞에서 사역동사에서 배운 구조다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>let + 사람 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>누구에게 ~하도록 허락하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>My parents \u003cstrong>let me stay\u003c/strong> up late.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>부모님은 내가 늦게까지 깨어 있어도 된다고 허락하셨다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">9. \u003ccode>let\u003c/code>에는 \u003ccode>to\u003c/code>가 없다\u003c/h2>\n\u003cp>중요하다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ let me go\u003cbr>❌ let me to go\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>✅ let him use it\u003cbr>❌ let him to use it\u003c/p>\n\u003c/blockquote>\n\u003cp>구조 자체가:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>let + 목적어 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">10. \u003ccode>let\u003c/code>과 \u003ccode>be allowed to\u003c/code> 비교\u003c/h2>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">허락하는 사람을 중심으로\u003c/h3>\n\u003cblockquote>\n\u003cp>My boss \u003cstrong>let me leave\u003c/strong> early.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>상사가 내가 일찍 퇴근하도록 허락했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">허락받은 사람을 중심으로\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>was allowed to leave\u003c/strong> early.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 일찍 퇴근해도 된다는 허락을 받았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>let = 허락하는 쪽\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>be allowed to = 허락받는 쪽\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">11. 능동과 수동 관계\u003c/h2>\n\u003cp>능동:\u003c/p>\n\u003cblockquote>\n\u003cp>My boss let me leave early.\u003c/p>\n\u003c/blockquote>\n\u003cp>수동 의미로 바꾸면 영어에서는 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>I was allowed to leave early.\u003c/p>\n\u003c/blockquote>\n\u003cp>를 쓴다.\u003c/p>\n\u003cp>\u003ccode>let\u003c/code>의 수동형을 그대로:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I was let to leave early.\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 만들지 않는 것이 기본이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">12. \u003ccode>allow + 사람 + to do\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>allow\u003c/code> 자체를 능동으로도 쓸 수 있다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>allow + 사람 + to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>My boss \u003cstrong>allowed me to leave\u003c/strong> early.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>상사가 내가 일찍 퇴근하도록 허락했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 \u003ccode>to\u003c/code>가 필요하다.\u003c/p>\n\u003cp>비교:\u003c/p>\n\u003cblockquote>\n\u003cp>let me \u003cstrong>leave\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>allow me \u003cstrong>to leave\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">13. 세 구조 비교\u003c/h2>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">\u003ccode>let\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>My parents \u003cstrong>let me play\u003c/strong> outside.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">\u003ccode>allow\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>My parents \u003cstrong>allowed me to play\u003c/strong> outside.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">\u003ccode>be allowed to\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>was allowed to play\u003c/strong> outside.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻은 비슷하지만 구조가 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">14. 의문문\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Am I allowed to sit here?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>제가 여기 앉아도 되나요?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Are we allowed to take photos?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>사진 찍어도 되나요?\u003c/p>\n\u003c/blockquote>\n\u003cp>실제 생활에서 아주 유용한 표현이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">핵심\u003c/h2>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">허락받음\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>be allowed to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;m allowed to use it.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">허락하지 않음\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>be not allowed to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;m not allowed to use it.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">누군가를 허락\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>let + 사람 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Let me go.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-27\" data-reading-anchor=\"reading-27\">\u003ccode>allow\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>allow + 사람 + to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They allowed me to go.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-28\" data-reading-anchor=\"reading-28\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>We are allowed to \u003cstrong>use / using\u003c/strong> this room.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Children are not allowed to \u003cstrong>enter / entering\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>My boss let me \u003cstrong>leave / to leave\u003c/strong> early.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>My boss allowed me \u003cstrong>leave / to leave\u003c/strong> early.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I \u003cstrong>was allowed to / was let to\u003c/strong> leave early.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003cstrong>Am I allowed to / Do I allowed to\u003c/strong> take photos here?\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>82단계 — \u003c/strong>\u003cstrong>\u003ccode>needn&#39;t / don&#39;t need to / don&#39;t have to\u003c/code>\u003c/strong>\u003cstrong>: “~할 필요가 없다”의 차이\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. be allowed to","depth":2},{"id":"reading-2","label":"2. 주어에 따라 be동사 변화","depth":2},{"id":"reading-3","label":"현재","depth":3},{"id":"reading-4","label":"3. 규칙상 허용","depth":2},{"id":"reading-5","label":"4. 부정형","depth":2},{"id":"reading-6","label":"5. can과 비교","depth":2},{"id":"reading-7","label":"can","depth":3},{"id":"reading-8","label":"be allowed to","depth":3},{"id":"reading-9","label":"6. 과거 허락","depth":2},{"id":"reading-10","label":"7. 미래 허락","depth":2},{"id":"reading-11","label":"8. let + 사람 + 동사원형","depth":2},{"id":"reading-12","label":"9. let에는 to가 없다","depth":2},{"id":"reading-13","label":"10. let과 be allowed to 비교","depth":2},{"id":"reading-14","label":"허락하는 사람을 중심으로","depth":3},{"id":"reading-15","label":"허락받은 사람을 중심으로","depth":3},{"id":"reading-16","label":"11. 능동과 수동 관계","depth":2},{"id":"reading-17","label":"12. allow + 사람 + to do","depth":2},{"id":"reading-18","label":"13. 세 구조 비교","depth":2},{"id":"reading-19","label":"let","depth":3},{"id":"reading-20","label":"allow","depth":3},{"id":"reading-21","label":"be allowed to","depth":3},{"id":"reading-22","label":"14. 의문문","depth":2},{"id":"reading-23","label":"핵심","depth":2},{"id":"reading-24","label":"허락받음","depth":3},{"id":"reading-25","label":"허락하지 않음","depth":3},{"id":"reading-26","label":"누군가를 허락","depth":3},{"id":"reading-27","label":"allow","depth":3},{"id":"reading-28","label":"연습","depth":2}],"origin":"notion","characters":3273,"aliases":{"structure":"reading-18","examples":"concept","contrast":"reading-6","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-4","topic-4":"reading-5","topic-5":"reading-6","topic-6":"reading-9","topic-7":"reading-10","topic-8":"reading-11","topic-9":"reading-12","topic-10":"reading-13","topic-11":"reading-16","topic-12":"reading-17"}},{"id":82,"title":"82단계 — needn't / don't need to / don't have to","html":"\u003ch1 id=\"lesson-title\" data-id=\"82\">82단계 — needn&#39;t / don&#39;t need to / don&#39;t have to\u003c/h1>\n\u003cp>이번에는 \u003cstrong>“~할 필요가 없다”\u003c/strong>를 표현하는 세 가지 구조를 구분한다.\u003c/p>\n\u003cp>핵심:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>needn&#39;t + 동사원형\u003c/strong>\u003cbr>\u003cstrong>don&#39;t need to + 동사원형\u003c/strong>\u003cbr>\u003cstrong>don&#39;t have to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>세 표현 모두 기본적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~할 필요가 없다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>don&#39;t have to\u003c/code>\u003c/h2>\n\u003cp>가장 기본적이고 회화에서 매우 자주 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>You \u003cstrong>don&#39;t have to come\u003c/strong> tomorrow.\u003cbr>너는 내일 올 필요 없어.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻은:\u003c/p>\n\u003cblockquote>\n\u003cp>와도 되고 안 와도 된다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 \u003cstrong>금지\u003c/strong>가 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>mustn&#39;t\u003c/code>와 반드시 구분\u003c/h2>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">don&#39;t have to\u003c/h3>\n\u003cblockquote>\n\u003cp>You \u003cstrong>don&#39;t have to wear\u003c/strong> a suit.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>정장을 입을 필요 없어.\u003c/p>\n\u003c/blockquote>\n\u003cp>입어도 된다.\u003c/p>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">mustn&#39;t\u003c/h3>\n\u003cblockquote>\n\u003cp>You \u003cstrong>mustn&#39;t wear\u003c/strong> shoes here.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>여기서는 신발을 신으면 안 된다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>don&#39;t have to = 불필요\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>mustn&#39;t = 금지\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>완전히 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. \u003ccode>don&#39;t need to\u003c/code>\u003c/h2>\n\u003cp>의미는 \u003ccode>don&#39;t have to\u003c/code>와 거의 같다.\u003c/p>\n\u003cblockquote>\n\u003cp>You \u003cstrong>don&#39;t need to bring\u003c/strong> anything.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>아무것도 가져올 필요 없어.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I \u003cstrong>don&#39;t need to work\u003c/strong> tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 내일 일할 필요가 없다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">비교\u003c/h2>\n\u003cblockquote>\n\u003cp>You don&#39;t have to come.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You don&#39;t need to come.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다:\u003c/p>\n\u003cblockquote>\n\u003cp>올 필요 없다.\u003c/p>\n\u003c/blockquote>\n\u003cp>일상에서는 상당히 비슷하게 사용된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">4. \u003ccode>needn&#39;t\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>need\u003c/code>를 조동사처럼 사용하는 형태다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>needn&#39;t + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>You \u003cstrong>needn&#39;t worry\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>걱정할 필요 없어.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You \u003cstrong>needn&#39;t come\u003c/strong> tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내일 올 필요 없어.\u003c/p>\n\u003c/blockquote>\n\u003cp>중요:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ needn&#39;t to come\u003cbr>✅ needn&#39;t come\u003c/p>\n\u003c/blockquote>\n\u003cp>조동사처럼 움직이기 때문에 \u003ccode>to\u003c/code>가 없다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. 세 표현 비교\u003c/h2>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">don&#39;t have to\u003c/h3>\n\u003cblockquote>\n\u003cp>You don&#39;t have to wait.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">don&#39;t need to\u003c/h3>\n\u003cblockquote>\n\u003cp>You don&#39;t need to wait.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">needn&#39;t\u003c/h3>\n\u003cblockquote>\n\u003cp>You needn&#39;t wait.\u003c/p>\n\u003c/blockquote>\n\u003cp>전부:\u003c/p>\n\u003cblockquote>\n\u003cp>기다릴 필요 없어.\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 의미다.\u003c/p>\n\u003cp>다만 \u003ccode>needn&#39;t\u003c/code>는 미국 영어 일상회화에서는 상대적으로 덜 흔하고, 영국 영어에서는 더 자주 볼 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">6. 긍정형 \u003ccode>need\u003c/code>\u003c/h2>\n\u003cp>일반동사로 쓰면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>need to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I need to go.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 가야 한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>주어가 \u003ccode>she\u003c/code>면:\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>needs to go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">부정\u003c/h2>\n\u003cblockquote>\n\u003cp>I \u003cstrong>don&#39;t need to go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>doesn&#39;t need to go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ She doesn&#39;t needs to go.\u003cbr>✅ She doesn&#39;t need to go.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">7. \u003ccode>needn&#39;t\u003c/code>는 주어에 따라 변하지 않는다\u003c/h2>\n\u003cp>조동사이기 때문이다.\u003c/p>\n\u003cblockquote>\n\u003cp>I needn&#39;t go.\u003cbr>She needn&#39;t go.\u003cbr>They needn&#39;t go.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ She needn&#39;t goes.\u003cbr>✅ She needn&#39;t go.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">8. 과거에서는 중요한 차이가 생긴다\u003c/h2>\n\u003cp>여기가 핵심이다.\u003c/p>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">\u003ccode>didn&#39;t need to + 동사\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>할 필요가 없었다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>didn&#39;t need to bring\u003c/strong> an umbrella.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>우산을 가져올 필요가 없었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 문장만으로는 실제로 우산을 가져왔는지 안 가져왔는지 확실하지 않다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">9. \u003ccode>needn&#39;t have + p.p.\u003c/code>\u003c/h2>\n\u003cp>이건 뜻이 다르다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>할 필요가 없었는데 실제로 해버렸다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>You \u003cstrong>needn&#39;t have bought\u003c/strong> so much food.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그렇게 많은 음식을 살 필요 없었는데.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>음식을 많이 샀다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">10. 비교\u003c/h2>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">didn&#39;t need to\u003c/h3>\n\u003cblockquote>\n\u003cp>I didn&#39;t need to take a taxi.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>택시를 탈 필요가 없었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로 택시를 탔는지는 문장만으로 알 수 없다.\u003c/p>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">needn&#39;t have\u003c/h3>\n\u003cblockquote>\n\u003cp>I needn&#39;t have taken a taxi.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>택시를 탈 필요가 없었는데 탔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>택시를 탔다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이 차이는 매우 중요하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">11. \u003ccode>shouldn&#39;t have\u003c/code>와도 다르다\u003c/h2>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">needn&#39;t have\u003c/h3>\n\u003cblockquote>\n\u003cp>You needn&#39;t have bought it.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그걸 살 필요 없었는데 샀네.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>불필요\u003c/strong>\u003c/p>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">shouldn&#39;t have\u003c/h3>\n\u003cblockquote>\n\u003cp>You shouldn&#39;t have bought it.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그걸 사지 말았어야 했어.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>잘못된 행동이라고 판단\u003c/strong>\u003c/p>\n\u003cp>뉘앙스가 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-24\" data-reading-anchor=\"reading-24\">12. 실제 회화 표현\u003c/h2>\n\u003cblockquote>\n\u003cp>You don&#39;t have to do that.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그렇게 할 필요 없어.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You don&#39;t need to explain.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>설명할 필요 없어.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You needn&#39;t worry.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>걱정할 필요 없어.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You needn&#39;t have done that.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그렇게까지 할 필요 없었는데.\u003c/p>\n\u003c/blockquote>\n\u003cp>마지막 표현은 누군가 지나치게 수고했을 때도 자주 쓸 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-25\" data-reading-anchor=\"reading-25\">핵심\u003c/h2>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">현재·미래의 불필요\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>don&#39;t have to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>don&#39;t need to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>needn&#39;t + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-27\" data-reading-anchor=\"reading-27\">과거에 필요 없었음\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>didn&#39;t need to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-28\" data-reading-anchor=\"reading-28\">필요 없었는데 실제로 함\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>needn&#39;t have + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-29\" data-reading-anchor=\"reading-29\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>You \u003cstrong>don&#39;t have to / mustn&#39;t\u003c/strong> come tomorrow.\u003c/p>\n\u003cp> → 올 필요 없음\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>You \u003cstrong>mustn&#39;t / don&#39;t need to\u003c/strong> touch this.\u003c/p>\n\u003cp> → 만지면 안 됨\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She \u003cstrong>doesn&#39;t need to / doesn&#39;t needs to\u003c/strong> work today.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>You \u003cstrong>needn&#39;t go / needn&#39;t to go\u003c/strong> now.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I \u003cstrong>didn&#39;t need to / needn&#39;t have\u003c/strong> bring any food.\u003c/p>\n\u003cp> → 가져올 필요가 없었다. 실제로 가져왔는지는 모름\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I \u003cstrong>needn&#39;t have bought / didn&#39;t need to bought\u003c/strong> so much food.\u003c/p>\n\u003cp> → 필요 없었는데 실제로 많이 샀음\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>83단계 — \u003c/strong>\u003cstrong>\u003ccode>may as well / might as well\u003c/code>\u003c/strong>\u003cstrong>: “그럴 바엔 ~하는 게 낫다”\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. don't have to","depth":2},{"id":"reading-2","label":"2. mustn't와 반드시 구분","depth":2},{"id":"reading-3","label":"don't have to","depth":3},{"id":"reading-4","label":"mustn't","depth":3},{"id":"reading-5","label":"3. don't need to","depth":2},{"id":"reading-6","label":"비교","depth":2},{"id":"reading-7","label":"4. needn't","depth":2},{"id":"reading-8","label":"5. 세 표현 비교","depth":2},{"id":"reading-9","label":"don't have to","depth":3},{"id":"reading-10","label":"don't need to","depth":3},{"id":"reading-11","label":"needn't","depth":3},{"id":"reading-12","label":"6. 긍정형 need","depth":2},{"id":"reading-13","label":"부정","depth":2},{"id":"reading-14","label":"7. needn't는 주어에 따라 변하지 않는다","depth":2},{"id":"reading-15","label":"8. 과거에서는 중요한 차이가 생긴다","depth":2},{"id":"reading-16","label":"didn't need to + 동사","depth":3},{"id":"reading-17","label":"9. needn't have + p.p.","depth":2},{"id":"reading-18","label":"10. 비교","depth":2},{"id":"reading-19","label":"didn't need to","depth":3},{"id":"reading-20","label":"needn't have","depth":3},{"id":"reading-21","label":"11. shouldn't have와도 다르다","depth":2},{"id":"reading-22","label":"needn't have","depth":3},{"id":"reading-23","label":"shouldn't have","depth":3},{"id":"reading-24","label":"12. 실제 회화 표현","depth":2},{"id":"reading-25","label":"핵심","depth":2},{"id":"reading-26","label":"현재·미래의 불필요","depth":3},{"id":"reading-27","label":"과거에 필요 없었음","depth":3},{"id":"reading-28","label":"필요 없었는데 실제로 함","depth":3},{"id":"reading-29","label":"연습","depth":2}],"origin":"notion","characters":3360,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-2","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-12","topic-8":"reading-13","topic-9":"reading-14","topic-10":"reading-15","topic-11":"reading-17","topic-12":"reading-18"}},{"id":83,"title":"83단계 — may as well / might as well","html":"\u003ch1 id=\"lesson-title\" data-id=\"83\">83단계 — may as well / might as well\u003c/h1>\n\u003cp>이번에는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>그럴 바엔 ~하는 게 낫다 / 이왕이면 ~하자\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 표현을 배운다.\u003c/p>\n\u003cp>핵심 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>may as well + 동사원형\u003c/strong>\u003cbr>\u003cstrong>might as well + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 의미는 매우 비슷하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 의미\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>We \u003cstrong>might as well go\u003c/strong> home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>우리 그냥 집에 가는 게 낫겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 표현은 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>다른 더 좋은 선택이 딱히 없으니 이걸 하자.\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 느낌이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 상황으로 이해하기\u003c/h2>\n\u003cp>예를 들어 영화관에 갔는데 표가 모두 매진됐다.\u003c/p>\n\u003cblockquote>\n\u003cp>The movie is sold out.\u003c/p>\n\u003c/blockquote>\n\u003cp>그러면:\u003c/p>\n\u003cblockquote>\n\u003cp>We \u003cstrong>might as well go\u003c/strong> home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>영화도 못 보니 그냥 집에 가는 게 낫겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>단순한 선호라기보다:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>상황을 보니 다른 선택을 할 이유가 별로 없다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>는 느낌이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>might as well + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ might as well \u003cstrong>go\u003c/strong>\u003cbr>❌ might as well \u003cstrong>to go\u003c/strong>\u003cbr>❌ might as well \u003cstrong>going\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>might\u003c/code>가 조동사이므로 뒤에는 동사원형이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>may as well\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>may as well\u003c/code>도 같은 식으로 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>We \u003cstrong>may as well start\u003c/strong> now.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이왕이면 지금 시작하자.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You \u003cstrong>may as well tell\u003c/strong> him the truth.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그럴 바엔 그에게 사실을 말하는 게 낫겠다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. \u003ccode>may as well\u003c/code>과 \u003ccode>might as well\u003c/code> 차이\u003c/h2>\n\u003cp>실제 회화에서는 의미가 많이 겹친다.\u003c/p>\n\u003cp>다만 \u003ccode>might as well\u003c/code>이 특히:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>어차피 / 기왕 이렇게 된 거\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 느낌으로 매우 자주 쓰인다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>It&#39;s already 10 p.m. We might as well stay here tonight.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>벌써 밤 10시네. 이왕 이렇게 된 거 오늘 밤은 여기 있는 게 낫겠다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">6. \u003ccode>should\u003c/code>와 차이\u003c/h2>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">should\u003c/h3>\n\u003cblockquote>\n\u003cp>You should go home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>집에 가는 게 좋아.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 조언\u003c/p>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">might as well\u003c/h3>\n\u003cblockquote>\n\u003cp>You might as well go home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>딱히 더 할 것도 없으니 그냥 집에 가는 게 낫겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>상황상 다른 선택지가 별로 없음\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. \u003ccode>would rather\u003c/code>와 차이\u003c/h2>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">would rather\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;d rather stay home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 차라리 집에 있고 싶다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>개인적인 선호\u003c/strong>\u003c/p>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">might as well\u003c/h3>\n\u003cblockquote>\n\u003cp>We might as well stay home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>상황이 이러니 그냥 집에 있는 게 낫겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>상황에 따른 현실적 선택\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">8. \u003ccode>had better\u003c/code>와도 다르다\u003c/h2>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">had better\u003c/h3>\n\u003cblockquote>\n\u003cp>You&#39;d better leave now.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>지금 출발하는 게 좋겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 안 그러면 문제가 생길 수 있음\u003c/p>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">might as well\u003c/h3>\n\u003cblockquote>\n\u003cp>We might as well leave now.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>딱히 더 있을 이유도 없으니 그냥 지금 가자.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 다른 더 나은 선택지가 없음\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">9. 부정형\u003c/h2>\n\u003cp>\u003ccode>might as well not + 동사원형\u003c/code>\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>We \u003cstrong>might as well not go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그럴 거면 그냥 안 가는 게 낫겠다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>If it&#39;s going to rain all day, we might as well not go out.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>하루 종일 비가 올 거면 그냥 안 나가는 게 낫겠다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">10. 자주 쓰는 표현\u003c/h2>\n\u003cblockquote>\n\u003cp>We might as well \u003cstrong>start\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그냥 시작하자.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I might as well \u003cstrong>try\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이왕 이렇게 된 거 한번 해보지 뭐.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You might as well \u003cstrong>ask\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이왕이면 물어보는 게 낫겠다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We might as well \u003cstrong>eat here\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그냥 여기서 먹자.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">11. \u003ccode>might as well\u003c/code>의 실제 감각\u003c/h2>\n\u003cp>이 표현은 한국어로 상황에 따라:\u003c/p>\n\u003cblockquote>\n\u003cp>그냥 ~하지 뭐\u003cbr>이왕이면 ~하자\u003cbr>이왕 이렇게 된 거 ~하자\u003cbr>그럴 바엔 ~하는 게 낫다\u003cbr>어차피 ~할 거면\u003c/p>\n\u003c/blockquote>\n\u003cp>등으로 자연스럽게 번역된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">핵심\u003c/h2>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">기본 구조\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>may/might as well + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">의미\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>다른 더 나은 선택이 없으니 그냥 ~하는 게 낫다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>We might as well go home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그냥 집에 가는 게 낫겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ might as well to go\u003cbr>✅ might as well go\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>We might as well \u003cstrong>go / to go\u003c/strong> home.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>It&#39;s already late. We \u003cstrong>might as well stay / should as well stay\u003c/strong> here.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I might as well \u003cstrong>try / trying\u003c/strong> it.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>We might as well \u003cstrong>not go / don&#39;t go\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“나는 차라리 집에 있고 싶다.”처럼 \u003cstrong>개인적인 선호\u003c/strong>\u003c/p>\n\u003cp> → \u003cstrong>I&#39;d rather stay home / I might as well stay home\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“어차피 다른 할 일도 없으니 그냥 시작하자.”\u003c/p>\n\u003cp> → We \u003cstrong>might as well start / had better start\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>84단계 — \u003c/strong>\u003cstrong>\u003ccode>be about to / be going to\u003c/code>\u003c/strong>\u003cstrong>: “막 ~하려던 참이다”와 계획된 미래의 차이\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 의미","depth":2},{"id":"reading-2","label":"2. 상황으로 이해하기","depth":2},{"id":"reading-3","label":"3. 구조","depth":2},{"id":"reading-4","label":"4. may as well","depth":2},{"id":"reading-5","label":"5. may as well과 might as well 차이","depth":2},{"id":"reading-6","label":"6. should와 차이","depth":2},{"id":"reading-7","label":"should","depth":3},{"id":"reading-8","label":"might as well","depth":3},{"id":"reading-9","label":"7. would rather와 차이","depth":2},{"id":"reading-10","label":"would rather","depth":3},{"id":"reading-11","label":"might as well","depth":3},{"id":"reading-12","label":"8. had better와도 다르다","depth":2},{"id":"reading-13","label":"had better","depth":3},{"id":"reading-14","label":"might as well","depth":3},{"id":"reading-15","label":"9. 부정형","depth":2},{"id":"reading-16","label":"10. 자주 쓰는 표현","depth":2},{"id":"reading-17","label":"11. might as well의 실제 감각","depth":2},{"id":"reading-18","label":"핵심","depth":2},{"id":"reading-19","label":"기본 구조","depth":3},{"id":"reading-20","label":"의미","depth":3},{"id":"reading-21","label":"연습","depth":2}],"origin":"notion","characters":2818,"aliases":{"structure":"reading-3","examples":"concept","contrast":"reading-5","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-9","topic-8":"reading-12","topic-9":"reading-15","topic-10":"reading-16","topic-11":"reading-17","topic-12":"reading-18"}},{"id":84,"title":"84단계 — be about to / be going to","html":"\u003ch1 id=\"lesson-title\" data-id=\"84\">84단계 — be about to / be going to\u003c/h1>\n\u003cp>이번에는 둘 다 미래를 가리키지만 \u003cstrong>시간적 거리가 다른 표현\u003c/strong>을 배운다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be about to + 동사원형\u003c/strong> = 막 ~하려는 참이다\u003cbr>\u003cstrong>be going to + 동사원형\u003c/strong> = ~할 계획이다 / ~할 것 같다\u003c/p>\n\u003c/blockquote>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>막 시작되기 직전인가, 앞으로 할 일인가?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>be about to\u003c/code>의 기본 의미\u003c/h2>\n\u003cblockquote>\n\u003cp>The train \u003cstrong>is about to leave\u003c/strong>.\u003cbr>기차가 막 출발하려 한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>한 달 뒤의 계획이 아니다. 지금 문이 닫히고 곧 움직일 것 같은 상황이다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am about to go\u003c/strong> out.\u003cbr>나 막 나가려던 참이야.\u003c/p>\n\u003c/blockquote>\n\u003cp>신발을 신고 문 앞에 있는 모습을 생각하면 된다. 현재형 \u003ccode>am about to\u003c/code>도 한국어 대화에서는 “막 나가려던 참이야”라고 자연스럽게 옮긴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + am/is/are + about to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>주어에 따라 바뀌는 것은 \u003ccode>be동사\u003c/code>다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am\u003c/strong> about to leave.\u003cbr>She \u003cstrong>is\u003c/strong> about to leave.\u003cbr>They \u003cstrong>are\u003c/strong> about to leave.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ is about to \u003cstrong>start\u003c/strong>\u003cbr>❌ is about to \u003cstrong>starting\u003c/strong>\u003cbr>❌ about to starts\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>about\u003c/code>을 “~에 관하여”라고 따로 해석하지 않는다. \u003cstrong>be about to 전체\u003c/strong>가 임박한 미래를 나타낸다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 사람의 계획에만 쓰는 것은 아니다\u003c/h2>\n\u003cblockquote>\n\u003cp>Look at that glass! It \u003cstrong>is about to fall\u003c/strong>.\u003cbr>저 유리잔 봐! 곧 떨어지겠어.\u003c/p>\n\u003c/blockquote>\n\u003cp>유리잔이 떨어질 계획을 세운 것이 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>The show \u003cstrong>is about to begin\u003c/strong>.\u003cbr>공연이 곧 시작하려 한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉, \u003cstrong>행동이나 사건이 시작되기 직전\u003c/strong>이면 사용할 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>be going to\u003c/code>와 비교\u003c/h2>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>going to call\u003c/strong> her tonight.\u003cbr>오늘 밤 그녀에게 전화할 생각이야.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 앞으로의 계획\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>about to call\u003c/strong> her.\u003cbr>지금 막 그녀에게 전화하려던 참이야.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 전화를 걸기 직전\u003c/p>\n\u003cp>같은 \u003ccode>call\u003c/code>이어도 초점이 다르다.\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\u003cthead>\u003ctr>\u003cth scope=\"col\">표현\u003c/th>\u003cth scope=\"col\">초점\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>be going to call\u003c/td>\u003ctd>전화할 계획·의도\u003c/td>\u003c/tr>\u003ctr>\u003ctd>be about to call\u003c/td>\u003ctd>전화가 시작되기 직전\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. \u003ccode>going to\u003c/code>는 눈앞의 근거로 예측할 때도 쓴다\u003c/h2>\n\u003cblockquote>\n\u003cp>Look at those dark clouds. It&#39;s \u003cstrong>going to rain\u003c/strong>.\u003cbr>저 먹구름 좀 봐. 비가 오겠어.\u003c/p>\n\u003c/blockquote>\n\u003cp>“비가 올 계획”이 아니라 \u003cstrong>현재 보이는 근거에 따른 예측\u003c/strong>이다.\u003c/p>\n\u003cblockquote>\n\u003cp>It&#39;s \u003cstrong>about to rain\u003c/strong>.\u003cbr>비가 막 쏟아지려 한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이쪽은 비가 시작될 때가 \u003cstrong>바로 코앞\u003c/strong>이라는 느낌을 더 강하게 준다.\u003c/p>\n\u003cp>따라서 \u003ccode>going to\u003c/code>를 항상 “미리 계획했다”로만 외우면 안 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">6. 먼 미래의 시간 표현과는 잘 맞지 않는다\u003c/h2>\n\u003cblockquote>\n\u003cp>We&#39;re \u003cstrong>going to move next year\u003c/strong>.\u003cbr>우리는 내년에 이사할 계획이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이때 \u003ccode>about to\u003c/code>를 쓰면 “바로 직전”이라는 뜻과 \u003ccode>next year\u003c/code>가 충돌한다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ We&#39;re about to move next year.\u003cbr>✅ We&#39;re going to move next year.\u003c/p>\n\u003c/blockquote>\n\u003cp>정확한 예정 시각을 말하는 것보다 \u003cstrong>지금 곧 일어남\u003c/strong>을 말하는 데 \u003ccode>about to\u003c/code>를 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">7. 과거: \u003ccode>was / were about to\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>I \u003cstrong>was about to leave\u003c/strong> when the phone rang.\u003cbr>막 떠나려던 참에 전화가 울렸다.\u003c/p>\n\u003c/blockquote>\n\u003cp>순서:\u003c/p>\n\u003col>\n\u003cli>\u003cp>떠날 준비가 되어 있었다.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>떠나기 직전에 전화가 울렸다.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>\u003ccode>was about to leave\u003c/code>만으로 실제로 떠났는지까지 확정되지는 않는다. 이 예문에서는 전화가 그 순간 끼어든 것이다.\u003c/p>\n\u003cblockquote>\n\u003cp>We \u003cstrong>were about to eat\u003c/strong> when the lights went out.\u003cbr>막 먹으려던 참에 불이 꺼졌다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">8. \u003ccode>was going to\u003c/code>와도 비교\u003c/h2>\n\u003cblockquote>\n\u003cp>I \u003cstrong>was going to call\u003c/strong> you, but I forgot.\u003cbr>너에게 전화하려고 했는데 잊어버렸어.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 과거에 가지고 있던 계획\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>was about to call\u003c/strong> you when you arrived.\u003cbr>막 전화하려던 순간 네가 도착했어.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 행동 직전의 순간\u003c/p>\n\u003cp>\u003ccode>was going to\u003c/code>는 문맥에 따라 계획이 실현되지 않았다는 뜻을 전달하지만, 형태 자체가 언제나 “결국 안 했다”를 뜻하는 것은 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">9. 부정문과 의문문\u003c/h2>\n\u003cp>be동사를 기준으로 만든다.\u003c/p>\n\u003cblockquote>\n\u003cp>The meeting \u003cstrong>isn&#39;t about to end\u003c/strong>.\u003cbr>회의가 곧 끝날 상황은 아니다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Are you about to leave?\u003c/strong>\u003cbr>지금 막 나가려는 거야?\u003c/p>\n\u003c/blockquote>\n\u003cp>다만 사람의 의지를 말할 때:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>not about to give up\u003c/strong>.\u003cbr>난 포기할 생각이 전혀 없어.\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 \u003ccode>not about to\u003c/code>가 \u003cstrong>그럴 의사가 없다\u003c/strong>는 강한 표현으로 쓰이기도 한다. 단순히 “아직 직전이 아니다”만으로 해석하지 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">핵심\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>be going to\u003c/strong> → 계획 또는 현재 근거에 따른 예측\u003cbr>\u003cstrong>be about to\u003c/strong> → 바로 일어나기 직전\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I was about to leave when you called.\u003cbr>네가 전화했을 때 나는 막 떠나려던 참이었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고 둘 다 뒤에는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">연습\u003c/h2>\n\u003cp>상황에 더 잘 맞거나 문법적으로 맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>기차 문이 닫혔다. 막 출발하려 한다.\u003c/p>\n\u003cp> → The train \u003cstrong>is about to leave / left yesterday\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>내년에 이사할 계획이다.\u003c/p>\n\u003cp> → We \u003cstrong>are going to move / are about to move\u003c/strong> next year.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She is about to \u003cstrong>speak / speaking\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I \u003cstrong>was / were\u003c/strong> about to leave when you called.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>먹구름을 보고 예측한다.\u003c/p>\n\u003cp> → It \u003cstrong>is going to rain / is going to raining\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“난 포기할 생각이 전혀 없어.”\u003c/p>\n\u003cp> → I&#39;m \u003cstrong>not about to give up / not about giving up\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>85단계 — 미래진행형 \u003c/strong>\u003cstrong>\u003ccode>will be + -ing\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. be about to의 기본 의미","depth":2},{"id":"reading-2","label":"2. 구조","depth":2},{"id":"reading-3","label":"3. 사람의 계획에만 쓰는 것은 아니다","depth":2},{"id":"reading-4","label":"4. be going to와 비교","depth":2},{"id":"reading-5","label":"5. going to는 눈앞의 근거로 예측할 때도 쓴다","depth":2},{"id":"reading-6","label":"6. 먼 미래의 시간 표현과는 잘 맞지 않는다","depth":2},{"id":"reading-7","label":"7. 과거: was / were about to","depth":2},{"id":"reading-8","label":"8. was going to와도 비교","depth":2},{"id":"reading-9","label":"9. 부정문과 의문문","depth":2},{"id":"reading-10","label":"핵심","depth":2},{"id":"reading-11","label":"연습","depth":2}],"origin":"notion","characters":3411,"aliases":{"structure":"reading-2","examples":"concept","contrast":"reading-4","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-7","topic-8":"reading-8","topic-9":"reading-9","topic-10":"reading-10","topic-11":"reading-11","topic-12":"concept"}},{"id":85,"title":"85단계 — 미래진행형 will be + -ing","html":"\u003ch1 id=\"lesson-title\" data-id=\"85\">85단계 — 미래진행형 will be + -ing\u003c/h1>\n\u003cp>지금 진행 중인 일을 말할 때는:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am working\u003c/strong>.\u003cbr>나는 일하고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이번에는 \u003cstrong>미래의 어느 순간에 진행 중일 일\u003c/strong>을 말한다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>will be working\u003c/strong>.\u003cbr>나는 일하고 있을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 미래의 한 장면을 떠올리기\u003c/h2>\n\u003cblockquote>\n\u003cp>At nine tomorrow morning, I \u003cstrong>will be taking\u003c/strong> an exam.\u003cbr>내일 아침 9시에 나는 시험을 보고 있을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>초점은 시험을 시작하는 순간도, 다 끝낸 결과도 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>내일 9시라는 시점에 시험이 진행 중이다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>사진을 한 장 찍었을 때 시험을 보고 있는 장면이라고 생각하면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + will + be + 동사-ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>하나씩 보면:\u003c/p>\n\u003cul>\n\u003cli>\u003cp>\u003ccode>will\u003c/code> = 미래를 바라봄\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003ccode>be + -ing\u003c/code> = 진행 중인 행동\u003c/p>\n\u003c/li>\n\u003c/ul>\n\u003cp>\u003ccode>will\u003c/code> 뒤에는 동사원형이 와야 하므로 \u003ccode>am / is / are\u003c/code>가 아니라 \u003cstrong>be\u003c/strong>다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ She will \u003cstrong>be studying\u003c/strong>.\u003cbr>❌ She will \u003cstrong>is studying\u003c/strong>.\u003cbr>❌ She will \u003cstrong>studying\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>주어가 달라져도:\u003c/p>\n\u003cblockquote>\n\u003cp>I will be working.\u003cbr>She will be working.\u003cbr>They will be working.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조는 같다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>this time tomorrow\u003c/code>\u003c/h2>\n\u003cp>미래진행형과 자주 만나는 표현이다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>This time tomorrow\u003c/strong>, we&#39;ll be flying to Seoul.\u003cbr>내일 이맘때 우리는 서울로 가는 비행기를 타고 있을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>At eight tonight\u003c/strong>, I&#39;ll be having dinner.\u003cbr>오늘 밤 8시에는 저녁을 먹고 있을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>시간 표현이 반드시 있어야 하는 것은 아니다. 대화에서 미래 시점이 이미 분명하면 생략할 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. 단순미래와 차이\u003c/h2>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">will + 동사원형\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;ll call you at eight.\u003cbr>8시에 전화할게.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 전화를 하겠다는 결정·약속\u003c/p>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">will be + -ing\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;ll be talking to a client at eight.\u003cbr>8시에는 고객과 통화하고 있을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 그 시각에 진행 중일 상황\u003c/p>\n\u003cp>둘 다 미래지만 \u003cstrong>행동을 어떤 모습으로 보여주는지\u003c/strong>가 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. 다른 일이 일어날 때 진행 중일 행동\u003c/h2>\n\u003cblockquote>\n\u003cp>When you arrive, I \u003cstrong>will be waiting\u003c/strong> outside.\u003cbr>네가 도착하면 나는 밖에서 기다리고 있을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cul>\n\u003cli>\u003cp>\u003ccode>when you arrive\u003c/code> = 미래의 기준 시점\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003ccode>will be waiting\u003c/code> = 그때 진행 중인 행동\u003c/p>\n\u003c/li>\n\u003c/ul>\n\u003cp>미래를 말하는 시간절에서는 보통 현재형을 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ When you \u003cstrong>arrive\u003c/strong>, I&#39;ll be waiting.\u003cbr>❌ When you \u003cstrong>will arrive\u003c/strong>, I&#39;ll be waiting.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 규칙은 \u003cstrong>미래 시간을 나타내는 when절\u003c/strong>에 관한 것이다. \u003ccode>I don&#39;t know when you will arrive.\u003c/code>의 간접의문문까지 금지하는 것은 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. 자연스럽게 예정된 일을 말하기\u003c/h2>\n\u003cblockquote>\n\u003cp>I&#39;ll \u003cstrong>be seeing\u003c/strong> Mina tomorrow, so I can give her your message.\u003cbr>내일 미나를 만날 예정이니까 네 말을 전해줄 수 있어.\u003c/p>\n\u003c/blockquote>\n\u003cp>꼭 “만나는 동작의 중간”을 강조하는 것만은 아니다. 일정상 또는 자연스러운 흐름으로 \u003cstrong>그 일이 있을 예정\u003c/strong>이라는 뜻으로도 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>We&#39;ll \u003cstrong>be staying\u003c/strong> with friends this weekend.\u003cbr>이번 주말에는 친구들 집에 머물 예정이야.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. 상대의 예정된 행동을 물을 때\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Will you be using\u003c/strong> the car this evening?\u003cbr>오늘 저녁에 차를 쓰실 예정인가요?\u003c/p>\n\u003c/blockquote>\n\u003cp>차를 빌려도 될지 알아보려고 상대의 일정을 묻는 상황이다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Will you use\u003c/strong> the car?\u003c/p>\n\u003c/blockquote>\n\u003cp>도 문법적으로 가능하지만, 문맥에 따라 의향을 직접 묻는 느낌이 난다. 미래진행형은 \u003cstrong>예정된 상황을 확인하는 질문\u003c/strong>에 잘 어울린다.\u003c/p>\n\u003cp>항상 더 공손하다고 기계적으로 바꾸기보다 질문의 목적을 생각한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. 부정문과 의문문\u003c/h2>\n\u003cp>부정은 \u003ccode>will\u003c/code> 뒤에 \u003ccode>not\u003c/code>을 넣는다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>won&#39;t be working\u003c/strong> tomorrow afternoon.\u003cbr>내일 오후에는 일하고 있지 않을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>의문문은 \u003ccode>will\u003c/code>을 앞으로 보낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Will she be staying\u003c/strong> here?\u003cbr>그녀는 여기 머물 예정인가요?\u003c/p>\n\u003c/blockquote>\n\u003cp>짧은 대답:\u003c/p>\n\u003cblockquote>\n\u003cp>Yes, she \u003cstrong>will\u003c/strong>.\u003cbr>No, she \u003cstrong>won&#39;t\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ Does she will be staying here?\u003cbr>✅ Will she be staying here?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">9. 모든 동사를 진행형으로 만드는 것은 아니다\u003c/h2>\n\u003cp>\u003ccode>know\u003c/code>, \u003ccode>believe\u003c/code>, 소유의 \u003ccode>have\u003c/code>처럼 상태를 나타내는 동사는 보통 진행형으로 쓰지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ I&#39;ll \u003cstrong>know\u003c/strong> the result tomorrow.\u003cbr>❌ I&#39;ll \u003cstrong>be knowing\u003c/strong> the result tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 같은 \u003ccode>have\u003c/code>라도 행동이면 가능하다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ll \u003cstrong>be having lunch\u003c/strong> at noon.\u003cbr>정오에는 점심을 먹고 있을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>단어 하나만 보고 결정하지 않고 \u003cstrong>그 문장에서의 의미\u003c/strong>를 본다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">핵심\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>미래진행형 = will be + -ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>주요 감각:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>미래의 그때 ~하고 있을 것이다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>This time tomorrow, I&#39;ll be travelling.\u003cbr>내일 이맘때는 여행 중일 거야.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">연습\u003c/h2>\n\u003col>\n\u003cli>\u003cp>At ten tonight, she will \u003cstrong>be studying / is studying\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I \u003cstrong>won&#39;t be working / don&#39;t will be working\u003c/strong> tomorrow.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003cstrong>Will you be using / Do you will be using\u003c/strong> this room?\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>When you \u003cstrong>arrive / will arrive\u003c/strong>, we&#39;ll be waiting outside.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>내일이면 결과를 알게 된다.\u003c/p>\n\u003cp> → I \u003cstrong>will know / will be knowing\u003c/strong> the result tomorrow.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“내일 이맘때 나는 비행기를 타고 있을 거야.”\u003c/p>\n\u003cp> → This time tomorrow, I \u003cstrong>will be flying / was flying\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>86단계 — 미래완료 \u003c/strong>\u003cstrong>\u003ccode>will have + p.p.\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 미래의 한 장면을 떠올리기","depth":2},{"id":"reading-2","label":"2. 구조","depth":2},{"id":"reading-3","label":"3. this time tomorrow","depth":2},{"id":"reading-4","label":"4. 단순미래와 차이","depth":2},{"id":"reading-5","label":"will + 동사원형","depth":3},{"id":"reading-6","label":"will be + -ing","depth":3},{"id":"reading-7","label":"5. 다른 일이 일어날 때 진행 중일 행동","depth":2},{"id":"reading-8","label":"6. 자연스럽게 예정된 일을 말하기","depth":2},{"id":"reading-9","label":"7. 상대의 예정된 행동을 물을 때","depth":2},{"id":"reading-10","label":"8. 부정문과 의문문","depth":2},{"id":"reading-11","label":"9. 모든 동사를 진행형으로 만드는 것은 아니다","depth":2},{"id":"reading-12","label":"핵심","depth":2},{"id":"reading-13","label":"연습","depth":2}],"origin":"notion","characters":3357,"aliases":{"structure":"reading-2","examples":"concept","contrast":"reading-4","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-12","topic-11":"reading-13","topic-12":"concept"}},{"id":86,"title":"86단계 — 미래완료 will have + p.p.","html":"\u003ch1 id=\"lesson-title\" data-id=\"86\">86단계 — 미래완료 will have + p.p.\u003c/h1>\n\u003cp>이번에는 미래의 한 시점에서 \u003cstrong>그때까지 끝나 있을 일\u003c/strong>을 말한다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>will have finished\u003c/strong> the report by Friday.\u003cbr>금요일까지는 보고서를 다 끝내 놓았을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>핵심 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>will have + 과거분사(p.p.)\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 미래에서 뒤를 돌아보기\u003c/h2>\n\u003cp>지금은 보고서를 쓰고 있다. 마감은 금요일이다.\u003c/p>\n\u003cp>금요일의 나를 상상하면:\u003c/p>\n\u003cblockquote>\n\u003cp>The report will be finished by then.\u003cbr>그때쯤이면 보고서가 끝나 있을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>내가 끝낸다는 행동으로 표현하면:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>will have finished\u003c/strong> the report by then.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>미래의 기준점 → 그때까지 이루어진 일을 돌아봄\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 구조를 나누어 보기\u003c/h2>\n\u003cblockquote>\n\u003cp>She \u003cstrong>will have left\u003c/strong> by noon.\u003cbr>정오까지는 그녀가 떠나 있을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>\u003cp>\u003ccode>will\u003c/code> = 미래의 관점\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003ccode>have + p.p.\u003c/code> = 그 기준점보다 앞선 일\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003ccode>left\u003c/code> = \u003ccode>leave\u003c/code>의 과거분사\u003c/p>\n\u003c/li>\n\u003c/ul>\n\u003cp>조동사 \u003ccode>will\u003c/code> 뒤이므로 주어가 \u003ccode>she\u003c/code>여도 \u003ccode>has\u003c/code>가 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ She will \u003cstrong>have left\u003c/strong>.\u003cbr>❌ She will \u003cstrong>has left\u003c/strong>.\u003cbr>❌ She will \u003cstrong>have leave\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>by\u003c/code>의 의미\u003c/h2>\n\u003cp>여기서 \u003ccode>by\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>늦어도 ~까지는\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이라는 뜻이다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ll have sent the email \u003cstrong>by five\u003c/strong>.\u003cbr>5시까지는 이메일을 보내 놓았을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>4시에 보내도 되고 4시 50분에 보내도 된다. \u003cstrong>5시를 기준으로 이미 완료된 상태\u003c/strong>라는 점이 중요하다.\u003c/p>\n\u003cp>자주 쓰는 표현:\u003c/p>\n\u003cblockquote>\n\u003cp>by tomorrow / by Friday / by then / by the end of the month\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>by\u003c/code>와 \u003ccode>until\u003c/code>은 다르다\u003c/h2>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">until\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;ll work \u003cstrong>until five\u003c/strong>.\u003cbr>5시까지 계속 일할 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 행동이 그때까지 지속\u003c/p>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">by\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;ll have finished \u003cstrong>by five\u003c/strong>.\u003cbr>5시까지는 일을 끝내 놓았을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 그 시점 이전 또는 그 시점까지 완료\u003c/p>\n\u003cp>\u003ccode>by\u003c/code>를 보면 무조건 미래완료라는 뜻도 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ll finish it by five.\u003c/p>\n\u003c/blockquote>\n\u003cp>도 자연스럽다. 미래완료는 특히 \u003cstrong>그때쯤 이미 끝나 있을 모습\u003c/strong>을 바라본다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. 미래진행형과 비교\u003c/h2>\n\u003cp>같은 내일 오후 3시라도:\u003c/p>\n\u003cblockquote>\n\u003cp>At three, I&#39;ll \u003cstrong>be writing\u003c/strong> the report.\u003cbr>3시에는 보고서를 쓰고 있을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 진행 중\u003c/p>\n\u003cblockquote>\n\u003cp>By three, I&#39;ll \u003cstrong>have written\u003c/strong> the report.\u003cbr>3시까지는 보고서를 다 써 놓았을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 완료된 상태\u003c/p>\n\u003cp>\u003ccode>be writing\u003c/code>과 \u003ccode>have written\u003c/code>이 보여주는 장면을 구별해야 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. \u003ccode>by the time + 절\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>By the time you arrive\u003c/strong>, we&#39;ll have eaten.\u003cbr>네가 도착할 때쯤이면 우리는 식사를 마쳤을 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>by the time\u003c/code> 뒤에는 주어와 동사가 있는 절이 온다.\u003c/p>\n\u003cp>이것은 미래를 나타내는 시간절이므로 보통 현재형을 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ by the time you \u003cstrong>arrive\u003c/strong>\u003cbr>❌ by the time you \u003cstrong>will arrive\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>미래완료는 주절의 \u003ccode>will have eaten\u003c/code>에 나타난다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. 기간이 그때까지 얼마나 쌓이는지도 말한다\u003c/h2>\n\u003cblockquote>\n\u003cp>Next June, we \u003cstrong>will have been married for ten years\u003c/strong>.\u003cbr>내년 6월이면 우리는 결혼한 지 10년이 된다.\u003c/p>\n\u003c/blockquote>\n\u003cp>결혼 생활이 그때 끝난다는 뜻이 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>미래 시점까지 이어진 기간이 10년이다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>By December, I \u003cstrong>will have known\u003c/strong> her for five years.\u003cbr>12월이면 그녀를 안 지 5년이 된다.\u003c/p>\n\u003c/blockquote>\n\u003cp>완료형은 “끝냈다”뿐 아니라 \u003cstrong>기준점까지의 지속\u003c/strong>도 표현한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. 부정문\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>will not have + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>축약하면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>won&#39;t have + p.p.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I \u003cstrong>won&#39;t have finished\u003c/strong> by lunchtime.\u003cbr>점심때까지는 다 끝내지 못했을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>그 이후에도 영원히 못 끝낸다는 뜻이 아니다. \u003cstrong>말한 기준점까지는 아직 완료되지 않는다\u003c/strong>는 뜻이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">9. 의문문과 짧은 대답\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Will + 주어 + have + p.p.?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Will you have finished\u003c/strong> by Friday?\u003cbr>금요일까지는 다 끝내 놓을 수 있겠어?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Yes, I \u003cstrong>will\u003c/strong>.\u003cbr>No, I \u003cstrong>won&#39;t\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>have\u003c/code>를 주어 앞으로 보내는 것이 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Have you will finished?\u003cbr>✅ Will you have finished?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">10. 과거분사 확인\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\u003cthead>\u003ctr>\u003cth scope=\"col\">동사원형\u003c/th>\u003cth scope=\"col\">과거형\u003c/th>\u003cth scope=\"col\">과거분사\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>finish\u003c/td>\u003ctd>finished\u003c/td>\u003ctd>finished\u003c/td>\u003c/tr>\u003ctr>\u003ctd>write\u003c/td>\u003ctd>wrote\u003c/td>\u003ctd>written\u003c/td>\u003c/tr>\u003ctr>\u003ctd>eat\u003c/td>\u003ctd>ate\u003c/td>\u003ctd>eaten\u003c/td>\u003c/tr>\u003ctr>\u003ctd>go\u003c/td>\u003ctd>went\u003c/td>\u003ctd>gone\u003c/td>\u003c/tr>\u003ctr>\u003ctd>do\u003c/td>\u003ctd>did\u003c/td>\u003ctd>done\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\n\u003cblockquote>\n\u003cp>✅ will have \u003cstrong>written\u003c/strong>\u003cbr>❌ will have \u003cstrong>wrote\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>will have\u003c/code> 뒤에 붙이는 것은 과거형이 아니라 \u003cstrong>과거분사\u003c/strong>다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">핵심\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>will have + p.p. = 미래의 그때까지 ~해 놓았을 것이다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>By the time you get home, I&#39;ll have cooked dinner.\u003cbr>네가 집에 도착할 때쯤이면 저녁을 다 만들어 놓았을 거야.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">연습\u003c/h2>\n\u003col>\n\u003cli>\u003cp>She will \u003cstrong>have finished / has finished\u003c/strong> by noon.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I&#39;ll have \u003cstrong>written / wrote\u003c/strong> the report by Friday.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“5시까지 계속 일한다.”\u003c/p>\n\u003cp> → I&#39;ll work \u003cstrong>until / by\u003c/strong> five.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>By the time you \u003cstrong>arrive / will arrive\u003c/strong>, we&#39;ll have eaten.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I \u003cstrong>won&#39;t have finished / won&#39;t finished\u003c/strong> by then.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>내년이면 그녀를 안 지 10년이다.\u003c/p>\n\u003cp> → I \u003cstrong>will have known / will have knowing\u003c/strong> her for ten years.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>87단계 — 미래완료진행형 \u003c/strong>\u003cstrong>\u003ccode>will have been + -ing\u003c/code>\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 미래에서 뒤를 돌아보기","depth":2},{"id":"reading-2","label":"2. 구조를 나누어 보기","depth":2},{"id":"reading-3","label":"3. by의 의미","depth":2},{"id":"reading-4","label":"4. by와 until은 다르다","depth":2},{"id":"reading-5","label":"until","depth":3},{"id":"reading-6","label":"by","depth":3},{"id":"reading-7","label":"5. 미래진행형과 비교","depth":2},{"id":"reading-8","label":"6. by the time + 절","depth":2},{"id":"reading-9","label":"7. 기간이 그때까지 얼마나 쌓이는지도 말한다","depth":2},{"id":"reading-10","label":"8. 부정문","depth":2},{"id":"reading-11","label":"9. 의문문과 짧은 대답","depth":2},{"id":"reading-12","label":"10. 과거분사 확인","depth":2},{"id":"reading-13","label":"핵심","depth":2},{"id":"reading-14","label":"연습","depth":2}],"origin":"notion","characters":3528,"aliases":{"structure":"reading-2","examples":"concept","contrast":"reading-7","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-12","topic-11":"reading-13","topic-12":"reading-14"}},{"id":87,"title":"87단계 — 미래완료진행형 will have been + -ing","html":"\u003ch1 id=\"lesson-title\" data-id=\"87\">87단계 — 미래완료진행형 will have been + -ing\u003c/h1>\n\u003cp>이번 표현은 길어 보이지만 이미 배운 두 가지를 합친 것이다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>완료 = 기준 시점까지 이어진 일\u003c/strong>\u003cbr>\u003cstrong>진행 = 계속되는 행동의 과정\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>핵심 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>will have been + 동사-ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>미래의 그때까지 얼마 동안 계속 ~하고 있을 것이다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 상황으로 이해하기\u003c/h2>\n\u003cp>나는 오전 9시에 공부를 시작한다. 정오에도 공부 중일 예정이다.\u003c/p>\n\u003cblockquote>\n\u003cp>By noon, I \u003cstrong>will have been studying for three hours\u003c/strong>.\u003cbr>정오가 되면 나는 세 시간 동안 공부하고 있는 셈이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>중요한 것은 “정오에 공부한다” 하나가 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>정오까지 쌓이는 공부 시간이 세 시간이다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 구조를 차례로 쌓기\u003c/h2>\n\u003cp>진행형:\u003c/p>\n\u003cblockquote>\n\u003cp>be studying\u003c/p>\n\u003c/blockquote>\n\u003cp>완료진행형:\u003c/p>\n\u003cblockquote>\n\u003cp>have been studying\u003c/p>\n\u003c/blockquote>\n\u003cp>미래완료진행형:\u003c/p>\n\u003cblockquote>\n\u003cp>will have been studying\u003c/p>\n\u003c/blockquote>\n\u003cp>왜 \u003ccode>been\u003c/code>일까?\u003c/p>\n\u003cp>\u003ccode>have\u003c/code> 다음에는 과거분사가 필요하고, \u003ccode>be\u003c/code>의 과거분사가 \u003cstrong>been\u003c/strong>이기 때문이다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ will \u003cstrong>have been working\u003c/strong>\u003cbr>❌ will \u003cstrong>has been working\u003c/strong>\u003cbr>❌ will \u003cstrong>have be working\u003c/strong>\u003cbr>❌ will \u003cstrong>have been work\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 자주 함께 나오는 시간 표현\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>by + 미래 시점\u003c/strong>\u003cbr>\u003cstrong>for + 기간\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>By next month, she \u003cstrong>will have been working\u003c/strong> here \u003cstrong>for a year\u003c/strong>.\u003cbr>다음 달이면 그녀가 여기서 일해 온 지 1년이 된다.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>\u003cp>\u003ccode>by next month\u003c/code> = 미래의 기준점\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003ccode>for a year\u003c/code> = 그때까지의 기간\u003c/p>\n\u003c/li>\n\u003c/ul>\n\u003cp>시작점을 말하려면 \u003ccode>since\u003c/code>도 가능하다.\u003c/p>\n\u003cblockquote>\n\u003cp>By six, we&#39;ll have been driving \u003cstrong>since noon\u003c/strong>.\u003cbr>6시가 되면 우리는 정오부터 계속 운전한 셈이다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. 미래진행형과 비교\u003c/h2>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">미래진행형\u003c/h3>\n\u003cblockquote>\n\u003cp>At noon, I&#39;ll \u003cstrong>be studying\u003c/strong>.\u003cbr>정오에는 공부하고 있을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 그 순간의 장면\u003c/p>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">미래완료진행형\u003c/h3>\n\u003cblockquote>\n\u003cp>By noon, I&#39;ll \u003cstrong>have been studying for three hours\u003c/strong>.\u003cbr>정오가 되면 세 시간째 공부 중일 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 그때까지 계속된 과정과 기간\u003c/p>\n\u003cp>둘 다 공부 중일 수 있지만, 두 번째에는 \u003cstrong>얼마나 오래 해 왔는지\u003c/strong>라는 관점이 더해진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. 미래완료와 비교\u003c/h2>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">완료된 양·결과\u003c/h3>\n\u003cblockquote>\n\u003cp>By Friday, I&#39;ll \u003cstrong>have written three reports\u003c/strong>.\u003cbr>금요일까지 보고서 세 개를 써 놓았을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">이어진 과정·기간\u003c/h3>\n\u003cblockquote>\n\u003cp>By Friday, I&#39;ll \u003cstrong>have been writing reports for a week\u003c/strong>.\u003cbr>금요일이면 일주일 동안 보고서를 쓰고 있는 셈이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>두 번째 문장은 보고서를 몇 개 완성했는지 알려주지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>몇 개를 끝냈나? → 완료형\u003c/strong>\u003cbr>\u003cstrong>얼마나 오래 계속했나? → 완료진행형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이 구별이 유용하지만, \u003ccode>live / work\u003c/code>처럼 두 형태가 겹치는 동사도 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">6. 그 시점 이후에도 반드시 계속되는가?\u003c/h2>\n\u003cblockquote>\n\u003cp>By six, I&#39;ll have been driving for five hours, so I&#39;ll need a break.\u003cbr>6시가 되면 다섯 시간 동안 운전한 셈이니 쉬어야 할 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>6시에 운전을 멈출 수도 있다.\u003c/p>\n\u003cp>완료진행형이 말하는 것은 \u003cstrong>기준점까지의 과정\u003c/strong>이다. 그 이후 계속할지는 문맥이 결정한다. 기준점 바로 전에 끝난 행동의 영향을 설명하는 경우도 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">7. 미래의 결과나 상태를 설명하기\u003c/h2>\n\u003cblockquote>\n\u003cp>She&#39;ll be tired when she arrives. She \u003cstrong>will have been travelling all day\u003c/strong>.\u003cbr>그녀는 도착하면 피곤할 것이다. 하루 종일 이동해 왔을 테니까.\u003c/p>\n\u003c/blockquote>\n\u003cp>“피곤할 것이다”라는 미래 상태에 대해 \u003cstrong>그 전까지 계속된 활동\u003c/strong>을 이유로 든다.\u003c/p>\n\u003cp>여기서 \u003ccode>for\u003c/code>가 반드시 있어야 하는 것은 아니다. \u003ccode>all day\u003c/code>도 지속 기간을 나타낸다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">8. 상태동사는 보통 완료형으로\u003c/h2>\n\u003cblockquote>\n\u003cp>By next year, I \u003cstrong>will have known\u003c/strong> him for ten years.\u003cbr>내년이면 그를 안 지 10년이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>know\u003c/code>는 보통 상태동사이므로:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ will have been knowing\u003cbr>✅ will have known\u003c/p>\n\u003c/blockquote>\n\u003cp>기간이 길다고 모든 문장을 완료진행형으로 바꾸는 것은 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">9. 부정문과 의문문\u003c/h2>\n\u003cp>부정:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>won&#39;t have been working\u003c/strong> here for very long by then.\u003cbr>그때까지는 내가 여기서 일한 기간이 그리 길지는 않을 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>의문:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>How long will you have been living\u003c/strong> here by next June?\u003cbr>내년 6월이면 여기서 산 지 얼마나 되는 거야?\u003c/p>\n\u003c/blockquote>\n\u003cp>형태:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Will + 주어 + have been + -ing?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>조동사 \u003ccode>will\u003c/code>만 주어 앞으로 보낸다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">핵심 비교\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\u003cthead>\u003ctr>\u003cth scope=\"col\">형태\u003c/th>\u003cth scope=\"col\">바라보는 것\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>will be working\u003c/td>\u003ctd>미래의 그때 진행 중인 일\u003c/td>\u003c/tr>\u003ctr>\u003ctd>will have finished\u003c/td>\u003ctd>그때까지 완료된 결과\u003c/td>\u003c/tr>\u003ctr>\u003ctd>will have been working\u003c/td>\u003ctd>그때까지 계속된 활동·기간\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\n\u003cblockquote>\n\u003cp>By next May, I&#39;ll have been teaching for five years.\u003cbr>내년 5월이면 가르친 지 5년이 된다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">연습\u003c/h2>\n\u003col>\n\u003cli>\u003cp>By noon, I will \u003cstrong>have been studying / has been studying\u003c/strong> for three hours.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She will have \u003cstrong>been working / be working\u003c/strong> here for a year.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“보고서를 세 개 완성해 놓을 것이다.”\u003c/p>\n\u003cp> → I&#39;ll \u003cstrong>have written three reports / have been writing three reports\u003c/strong> by Friday.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>By next year, I \u003cstrong>will have known / will have been knowing\u003c/strong> her for ten years.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>How long \u003cstrong>will you have been waiting / you will have been waiting\u003c/strong> by five?\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“내일 이맘때의 진행 장면만” 말한다.\u003c/p>\n\u003cp> → This time tomorrow, I \u003cstrong>will be flying / will have flew\u003c/strong> to Seoul.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>88단계 — 무관사와 일반적 의미\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 상황으로 이해하기","depth":2},{"id":"reading-2","label":"2. 구조를 차례로 쌓기","depth":2},{"id":"reading-3","label":"3. 자주 함께 나오는 시간 표현","depth":2},{"id":"reading-4","label":"4. 미래진행형과 비교","depth":2},{"id":"reading-5","label":"미래진행형","depth":3},{"id":"reading-6","label":"미래완료진행형","depth":3},{"id":"reading-7","label":"5. 미래완료와 비교","depth":2},{"id":"reading-8","label":"완료된 양·결과","depth":3},{"id":"reading-9","label":"이어진 과정·기간","depth":3},{"id":"reading-10","label":"6. 그 시점 이후에도 반드시 계속되는가?","depth":2},{"id":"reading-11","label":"7. 미래의 결과나 상태를 설명하기","depth":2},{"id":"reading-12","label":"8. 상태동사는 보통 완료형으로","depth":2},{"id":"reading-13","label":"9. 부정문과 의문문","depth":2},{"id":"reading-14","label":"핵심 비교","depth":2},{"id":"reading-15","label":"연습","depth":2}],"origin":"notion","characters":3507,"aliases":{"structure":"reading-2","examples":"concept","contrast":"reading-4","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-7","topic-6":"reading-10","topic-7":"reading-11","topic-8":"reading-12","topic-9":"reading-13","topic-10":"reading-14","topic-11":"reading-15","topic-12":"concept"}},{"id":88,"title":"88단계 — 무관사(Zero Article)와 일반적 의미","html":"\u003ch1 id=\"lesson-title\" data-id=\"88\">88단계 — 무관사(Zero Article)와 일반적 의미\u003c/h1>\n\u003cp>앞에서는 \u003ccode>a / an / the\u003c/code>를 배웠다.\u003c/p>\n\u003cp>이번에는 \u003cstrong>관사를 쓰지 않는 경우\u003c/strong>를 배운다.\u003c/p>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>dogs\u003c/strong>.\u003cbr>나는 개를 좋아한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>왜 \u003ccode>the dogs\u003c/code>가 아닐까?\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>어떤 특정한 개들이 아니라, 개라는 동물 전반을 말하기 때문이다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>관사가 없는 형태를 \u003cstrong>무관사(Zero Article)\u003c/strong>라고 부른다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 복수 가산명사를 일반적으로 말할 때\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Cats\u003c/strong> sleep a lot.\u003cbr>고양이는 잠을 많이 잔다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Children\u003c/strong> need enough sleep.\u003cbr>아이들은 충분한 수면이 필요하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>복수 명사 앞에 관사를 붙이지 않고 \u003cstrong>그 종류 전반\u003c/strong>을 말한다.\u003c/p>\n\u003cp>이때 단수로 아무렇게나 바꾸면 안 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I like dog.\u003cbr>✅ I like dogs.\u003c/p>\n\u003c/blockquote>\n\u003cp>단수 가산명사는 보통 \u003ccode>a / the / my / this\u003c/code> 같은 한정사가 필요하다. 음식으로서의 \u003ccode>dog\u003c/code>처럼 다른 뜻으로 바뀌는 특수 문맥은 별개다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 불가산명사를 일반적으로 말할 때\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Water\u003c/strong> is essential.\u003cbr>물은 필수적이다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Music\u003c/strong> helps me relax.\u003cbr>음악은 내가 긴장을 푸는 데 도움이 된다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I need \u003cstrong>information\u003c/strong>.\u003cbr>정보가 필요하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>water / music / information\u003c/code>은 여기서 셀 수 없는 명사다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ an information\u003cbr>✅ information\u003cbr>✅ a piece of information\u003c/p>\n\u003c/blockquote>\n\u003cp>무관사는 “복수일 때만” 쓰는 것이 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 특정해지면 \u003ccode>the\u003c/code>\u003c/h2>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">일반적인 물\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>Water\u003c/strong> freezes at 0°C under ordinary conditions.\u003cbr>일반적인 조건에서 물은 섭씨 0도에 언다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">특정한 물\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>The water in this bottle\u003c/strong> is cold.\u003cbr>이 병에 든 물은 차갑다.\u003c/p>\n\u003c/blockquote>\n\u003cp>같은 불가산명사라도 특정 대상을 가리키면 \u003ccode>the\u003c/code>를 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>books\u003c/strong>.\u003cbr>나는 책을 좋아한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>the books you gave me\u003c/strong>.\u003cbr>네가 준 그 책들이 마음에 든다.\u003c/p>\n\u003c/blockquote>\n\u003cp>중요한 질문:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>종류 전반인가, 서로 알고 있는 특정 대상인가?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 추상적인 개념도 같은 원리\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Life\u003c/strong> can be difficult.\u003cbr>삶은 힘들 때가 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>The life of a doctor\u003c/strong> can be stressful.\u003cbr>의사의 삶은 스트레스가 많을 수 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Love\u003c/strong> is important.\u003cbr>사랑은 중요하다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>The love she showed me\u003c/strong> changed my life.\u003cbr>그녀가 내게 보여준 사랑은 내 삶을 바꿨다.\u003c/p>\n\u003c/blockquote>\n\u003cp>명사 뒤에 수식어가 있다고 무조건 \u003ccode>the\u003c/code>가 필요한 것은 아니다. \u003cstrong>대상을 특정하는지\u003c/strong>가 기준이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. 식사 이름\u003c/h2>\n\u003cp>일상적인 식사를 말할 때:\u003c/p>\n\u003cblockquote>\n\u003cp>We have \u003cstrong>breakfast\u003c/strong> at seven.\u003cbr>우리는 7시에 아침을 먹는다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Let&#39;s have \u003cstrong>lunch\u003c/strong>.\u003cbr>점심 먹자.\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 한 번의 식사를 성격과 함께 표현하면:\u003c/p>\n\u003cblockquote>\n\u003cp>We had \u003cstrong>a lovely dinner\u003c/strong>.\u003cbr>우리는 멋진 저녁 식사를 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>특정 식사라면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>The dinner we had yesterday\u003c/strong> was wonderful.\u003cbr>어제 먹은 저녁 식사는 훌륭했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>breakfast / lunch / dinner\u003c/code> 앞에 관사가 절대 못 오는 것은 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. 언어·과목·운동 이름\u003c/h2>\n\u003cblockquote>\n\u003cp>She speaks \u003cstrong>English\u003c/strong>.\u003cbr>그녀는 영어를 한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I study \u003cstrong>history\u003c/strong>.\u003cbr>나는 역사를 공부한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They play \u003cstrong>tennis\u003c/strong>.\u003cbr>그들은 테니스를 친다.\u003c/p>\n\u003c/blockquote>\n\u003cp>다만:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>the English language\u003c/strong>\u003cbr>영어라는 언어\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 명사구의 구조가 달라지면 관사도 달라질 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. \u003ccode>school / bed / work\u003c/code>의 관용적인 사용\u003c/h2>\n\u003cblockquote>\n\u003cp>The children go to \u003cstrong>school\u003c/strong>.\u003cbr>아이들은 학교에 다닌다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;m going to \u003cstrong>bed\u003c/strong>.\u003cbr>나 자러 갈게.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She&#39;s at \u003cstrong>work\u003c/strong>.\u003cbr>그녀는 일하는 중이다 / 직장에 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 건물이나 물건 자체보다 \u003cstrong>그 장소의 통상적인 활동\u003c/strong>을 말한다.\u003c/p>\n\u003cp>비교:\u003c/p>\n\u003cblockquote>\n\u003cp>I went to \u003cstrong>the school\u003c/strong> to meet the principal.\u003cbr>교장 선생님을 만나러 그 학교에 갔다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>The cat is on \u003cstrong>the bed\u003c/strong>.\u003cbr>고양이가 그 침대 위에 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 규칙을 모든 장소 명사에 적용하면 안 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ go to \u003cstrong>the bank\u003c/strong>\u003cbr>❌ go to bank\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. 지역 차이도 있다\u003c/h2>\n\u003cp>환자로 입원해 있다는 뜻으로 영국 영어에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>She&#39;s \u003cstrong>in hospital\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>미국 영어에서는 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>She&#39;s \u003cstrong>in the hospital\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>이라고 한다.\u003c/p>\n\u003cp>관사를 썼다는 이유만으로 미국식 표현을 틀렸다고 판단하지 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">9. 사람·나라 이름과 관사\u003c/h2>\n\u003cblockquote>\n\u003cp>Mina lives in \u003cstrong>Korea\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>많은 고유명사는 관사 없이 쓴다. 하지만 예외도 함께 익혀야 한다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>the United States\u003c/strong>\u003cbr>\u003cstrong>the Netherlands\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>“나라 이름 앞에는 무조건 무관사”가 아니라 \u003cstrong>이름별 관용\u003c/strong>을 확인한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">핵심\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>복수 가산명사·불가산명사의 일반적 의미 → 관사 없이 쓰는 경우가 많다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>music\u003c/strong>.\u003cbr>I like \u003cstrong>the music in this film\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>관사의 유무는 단순한 장식이 아니라 \u003cstrong>어떤 범위의 대상을 말하는지\u003c/strong>를 보여준다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">연습\u003c/h2>\n\u003col>\n\u003cli>\u003cp>개라는 동물 전반이 좋다. → I like \u003cstrong>dogs / the dogs\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>이 병에 든 물 → \u003cstrong>Water / The water\u003c/strong> in this bottle is warm.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She speaks \u003cstrong>English / an English\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>학교에 다닌다. → They go to \u003cstrong>school / a school building\u003c/strong> every day.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“멋진 저녁 식사 한 번” → We had \u003cstrong>a lovely dinner / lovely dinner\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I need \u003cstrong>information / an information\u003c/strong> about the course.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>89단계 — 수량표현 \u003c/strong>\u003cstrong>\u003ccode>much / many / few / little\u003c/code>\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 복수 가산명사를 일반적으로 말할 때","depth":2},{"id":"reading-2","label":"2. 불가산명사를 일반적으로 말할 때","depth":2},{"id":"reading-3","label":"3. 특정해지면 the","depth":2},{"id":"reading-4","label":"일반적인 물","depth":3},{"id":"reading-5","label":"특정한 물","depth":3},{"id":"reading-6","label":"4. 추상적인 개념도 같은 원리","depth":2},{"id":"reading-7","label":"5. 식사 이름","depth":2},{"id":"reading-8","label":"6. 언어·과목·운동 이름","depth":2},{"id":"reading-9","label":"7. school / bed / work의 관용적인 사용","depth":2},{"id":"reading-10","label":"8. 지역 차이도 있다","depth":2},{"id":"reading-11","label":"9. 사람·나라 이름과 관사","depth":2},{"id":"reading-12","label":"핵심","depth":2},{"id":"reading-13","label":"연습","depth":2}],"origin":"notion","characters":3349,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-10","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-12","topic-11":"reading-13","topic-12":"concept"}},{"id":89,"title":"89단계 — 수량표현 much / many / a lot of / few / little","html":"\u003ch1 id=\"lesson-title\" data-id=\"89\">89단계 — 수량표현 much / many / a lot of / few / little\u003c/h1>\n\u003cp>이번에는 “많다”와 “적다”를 영어로 표현한다.\u003c/p>\n\u003cp>가장 먼저 확인할 것은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>뒤의 명사를 셀 수 있는가?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\u003cthead>\u003ctr>\u003cth scope=\"col\">명사\u003c/th>\u003cth scope=\"col\">많다\u003c/th>\u003cth scope=\"col\">적다\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>복수 가산명사\u003c/td>\u003ctd>many\u003c/td>\u003ctd>few / a few\u003c/td>\u003c/tr>\u003ctr>\u003ctd>불가산명사\u003c/td>\u003ctd>much\u003c/td>\u003ctd>little / a little\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>many + 복수 가산명사\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>many books\u003c/strong>.\u003cbr>나는 책이 많다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Are there \u003cstrong>many people\u003c/strong> here?\u003cbr>여기에 사람이 많니?\u003c/p>\n\u003c/blockquote>\n\u003cp>하나, 둘 셀 수 있는 명사는 복수형으로 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ many \u003cstrong>questions\u003c/strong>\u003cbr>❌ many \u003cstrong>question\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>people\u003c/code>은 이미 복수 의미이므로 일반적인 “사람들”에 \u003ccode>peoples\u003c/code>를 쓰지 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>much + 불가산명사\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>We don&#39;t have \u003cstrong>much time\u003c/strong>.\u003cbr>우리에게 시간이 많지 않다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Do you have \u003cstrong>much money\u003c/strong>?\u003cbr>돈이 많니?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>✅ much \u003cstrong>information\u003c/strong>\u003cbr>❌ many \u003cstrong>informations\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>한국어에서 셀 수 있을 것처럼 느껴져도 영어의 용법을 따른다. \u003ccode>money / time / advice / information\u003c/code>은 이 의미에서 불가산명사다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>a lot of\u003c/code>는 둘 다 가능\u003c/h2>\n\u003cblockquote>\n\u003cp>She has \u003cstrong>a lot of friends\u003c/strong>.\u003cbr>그녀는 친구가 많다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We have \u003cstrong>a lot of work\u003c/strong> to do.\u003cbr>우리는 할 일이 많다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>a lot of + 복수 가산명사 / 불가산명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>일상적인 긍정문에서는 \u003ccode>much\u003c/code>보다 \u003ccode>a lot of\u003c/code>가 자연스러운 경우가 많다.\u003c/p>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>a lot of time\u003c/strong> today.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>I have much time.\u003c/code>은 문맥 없이 일상 대화에서 쓰면 딱딱하거나 어색하다. 하지만 \u003ccode>so much / too much / how much\u003c/code>에서는 \u003ccode>much\u003c/code>를 자연스럽게 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>few\u003c/code>와 \u003ccode>a few\u003c/code>\u003c/h2>\n\u003cp>둘 다 복수 가산명사와 쓴다.\u003c/p>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">few\u003c/h3>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>few friends\u003c/strong> here.\u003cbr>나는 여기 친구가 거의 없다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 적다는 점, 부족하다는 느낌\u003c/p>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">a few\u003c/h3>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>a few friends\u003c/strong> here.\u003cbr>나는 여기 친구가 몇 명 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 많지는 않지만 있다는 점\u003c/p>\n\u003cp>단순히 숫자가 정해져 있는 것이 아니다. 같은 수여도 화자가 \u003cstrong>부족함을 말하는지, 존재를 말하는지\u003c/strong>가 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. \u003ccode>little\u003c/code>과 \u003ccode>a little\u003c/code>\u003c/h2>\n\u003cp>불가산명사에서도 같은 대비가 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>We have \u003cstrong>little time\u003c/strong>.\u003cbr>우리에게 시간이 거의 없다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We have \u003cstrong>a little time\u003c/strong>.\u003cbr>우리에게 시간이 조금 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>상황을 붙이면:\u003c/p>\n\u003cblockquote>\n\u003cp>We have little time, so hurry.\u003cbr>시간이 거의 없으니 서둘러.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We have a little time, so let&#39;s get coffee.\u003cbr>시간이 조금 있으니 커피를 마시자.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>a\u003c/code> 하나가 문장의 관점을 바꾼다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. \u003ccode>only a few / only a little\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>Only \u003cstrong>a few people\u003c/strong> came.\u003cbr>몇 명밖에 오지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>a few\u003c/code> 앞에 \u003ccode>only\u003c/code>가 붙으면 적다는 점을 다시 강조한다.\u003c/p>\n\u003cblockquote>\n\u003cp>There&#39;s only \u003cstrong>a little milk\u003c/strong> left.\u003cbr>우유가 조금밖에 남지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서 \u003ccode>a few\u003c/code>가 들어 있으면 언제나 긍정적인 감정이라는 뜻은 아니다. \u003cstrong>문장 전체\u003c/strong>를 읽어야 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. \u003ccode>too many\u003c/code>와 \u003ccode>too much\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>too\u003c/code>는 필요한 정도를 넘었다는 뜻이다.\u003c/p>\n\u003cblockquote>\n\u003cp>There are \u003cstrong>too many cars\u003c/strong>.\u003cbr>차가 너무 많다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>There&#39;s \u003cstrong>too much noise\u003c/strong>.\u003cbr>소음이 너무 심하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>비교:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>a lot of work\u003c/strong> = 많은 일\u003cbr>\u003cstrong>too much work\u003c/strong> = 감당하기에 너무 많은 일\u003c/p>\n\u003c/blockquote>\n\u003cp>“아주 많다”와 “지나치게 많다”는 같지 않다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. \u003ccode>fewer\u003c/code>와 \u003ccode>less\u003c/code>\u003c/h2>\n\u003cp>적은 정도를 비교하면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>fewer + 복수 가산명사\u003c/strong>\u003cbr>\u003cstrong>less + 불가산명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We need \u003cstrong>fewer chairs\u003c/strong>.\u003cbr>의자가 더 적게 필요하다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We need \u003cstrong>less water\u003c/strong>.\u003cbr>물이 더 적게 필요하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>수량을 하나씩 세는 \u003ccode>chairs\u003c/code>에는 \u003ccode>fewer\u003c/code>, 양으로 보는 \u003ccode>water\u003c/code>에는 \u003ccode>less\u003c/code>가 기본이다. 시간·거리·돈을 하나의 양으로 말할 때는 \u003ccode>less than ten minutes\u003c/code>처럼 숫자와도 \u003ccode>less\u003c/code>를 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">9. 특정 집단의 일부: \u003ccode>of\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>many students\u003c/strong>\u003cbr>많은 학생들\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>many of the students\u003c/strong>\u003cbr>그 학생들 중 많은 수\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>a few of my friends\u003c/strong>\u003cbr>내 친구들 중 몇 명\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>a little of this soup\u003c/strong>\u003cbr>이 수프의 조금\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>the / my / these\u003c/code>로 특정된 집단이나 양의 일부를 말할 때 \u003ccode>of\u003c/code>를 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ many of students\u003cbr>✅ many students\u003cbr>✅ many of the students\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">10. 동사도 뒤의 명사에 맞춘다\u003c/h2>\n\u003cblockquote>\n\u003cp>A lot of \u003cstrong>people are\u003c/strong> waiting.\u003cbr>많은 사람들이 기다리고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>A lot of \u003cstrong>water is\u003c/strong> wasted.\u003cbr>많은 물이 낭비된다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>a lot\u003c/code>에 \u003ccode>a\u003c/code>가 있다고 무조건 단수동사를 쓰지 않는다. 실제 수량을 말하는 \u003cstrong>명사\u003c/strong>를 본다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">핵심\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>many / few / a few → 셀 수 있는 복수\u003c/strong>\u003cbr>\u003cstrong>much / little / a little → 셀 수 없는 양\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>few / little = 거의 없다\u003c/strong>\u003cbr>\u003cstrong>a few / a little = 조금 있다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">연습\u003c/h2>\n\u003col>\n\u003cli>\u003cp>We don&#39;t have \u003cstrong>many / much\u003c/strong> time.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>There are \u003cstrong>a few / a little\u003c/strong> chairs left.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“시간이 거의 없으니 서둘러.” → We have \u003cstrong>little / a little\u003c/strong> time, so hurry.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She gave me \u003cstrong>a lot of advice / many advices\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>A lot of students \u003cstrong>is / are\u003c/strong> waiting.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>내 친구들 중 몇 명 → \u003cstrong>a few of my friends / a few my friends\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>더 적은 병들 → \u003cstrong>fewer bottles / less bottles\u003c/strong>\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>90단계 — \u003c/strong>\u003cstrong>\u003ccode>each / every / all / both / either / neither\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. many + 복수 가산명사","depth":2},{"id":"reading-2","label":"2. much + 불가산명사","depth":2},{"id":"reading-3","label":"3. a lot of는 둘 다 가능","depth":2},{"id":"reading-4","label":"4. few와 a few","depth":2},{"id":"reading-5","label":"few","depth":3},{"id":"reading-6","label":"a few","depth":3},{"id":"reading-7","label":"5. little과 a little","depth":2},{"id":"reading-8","label":"6. only a few / only a little","depth":2},{"id":"reading-9","label":"7. too many와 too much","depth":2},{"id":"reading-10","label":"8. fewer와 less","depth":2},{"id":"reading-11","label":"9. 특정 집단의 일부: of","depth":2},{"id":"reading-12","label":"10. 동사도 뒤의 명사에 맞춘다","depth":2},{"id":"reading-13","label":"핵심","depth":2},{"id":"reading-14","label":"연습","depth":2}],"origin":"notion","characters":3583,"aliases":{"structure":"concept","examples":"concept","contrast":"concept","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-12","topic-11":"reading-13","topic-12":"reading-14"}},{"id":90,"title":"90단계 — each / every / all / both / either / neither","html":"\u003ch1 id=\"lesson-title\" data-id=\"90\">90단계 — each / every / all / both / either / neither\u003c/h1>\n\u003cp>이번에는 집단을 바라보는 방법을 배운다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>하나씩 보는가? 전체로 보는가? 둘 중에서 고르는가?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이 차이가 단어와 동사의 형태를 결정한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>each\u003c/code> — 각각\u003c/h2>\n\u003cp>집단의 구성원을 \u003cstrong>하나씩 따로\u003c/strong> 바라본다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Each student\u003c/strong> has a notebook.\u003cbr>학생마다 공책을 가지고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>each + 단수명사 + 단수동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>학생이 여러 명이어도 한 명씩 보는 표현이다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ Each student \u003cstrong>has\u003c/strong> a book.\u003cbr>❌ Each students have a book.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>every\u003c/code> — 모두가 빠짐없이\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Every student\u003c/strong> has a notebook.\u003cbr>모든 학생이 공책을 가지고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조는 역시:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>every + 단수명사 + 단수동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>each\u003c/code>가 개별 구성원에 시선을 두면, \u003ccode>every\u003c/code>는 \u003cstrong>집단에서 예외가 없음\u003c/strong>에 시선을 둔다. 많은 상황에서는 둘 다 가능하다.\u003c/p>\n\u003cblockquote>\n\u003cp>I checked \u003cstrong>each answer\u003c/strong> carefully.\u003cbr>답을 하나하나 꼼꼼하게 확인했다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Every answer\u003c/strong> was correct.\u003cbr>모든 답이 맞았다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 둘일 때는 \u003ccode>each\u003c/code>, 셋 이상에는 \u003ccode>every\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>She wore a ring on \u003cstrong>each hand\u003c/strong>.\u003cbr>그녀는 양손에 각각 반지를 끼고 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>손이 둘일 때 \u003ccode>each\u003c/code>를 쓸 수 있다.\u003c/p>\n\u003cp>\u003ccode>every\u003c/code>는 보통 셋 이상의 구성원으로 이루어진 집단에 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>every student in the class\u003c/p>\n\u003c/blockquote>\n\u003cp>둘만을 말한다면 \u003ccode>each\u003c/code>나 \u003ccode>both\u003c/code>를 선택한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>all\u003c/code> — 전체\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>All the students\u003c/strong> are ready.\u003cbr>학생들이 모두 준비되었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>복수명사 전체를 말하므로 동사도 복수다.\u003c/p>\n\u003cblockquote>\n\u003cp>Every student \u003cstrong>is\u003c/strong> ready.\u003cbr>All the students \u003cstrong>are\u003c/strong> ready.\u003c/p>\n\u003c/blockquote>\n\u003cp>불가산명사와도 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>All the water is\u003c/strong> gone.\u003cbr>물이 전부 없어졌다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>all\u003c/code> 자체가 무조건 복수라는 뜻은 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. \u003ccode>both\u003c/code> — 둘 다\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Both answers\u003c/strong> are correct.\u003cbr>두 답이 모두 맞다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Both of my parents\u003c/strong> work.\u003cbr>부모님 두 분 모두 일하신다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>both + 복수명사 + 복수동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>✅ Both books \u003cstrong>are\u003c/strong> useful.\u003cbr>❌ Both book is useful.\u003c/p>\n\u003c/blockquote>\n\u003cp>셋 이상인 집단 전체에는 \u003ccode>both\u003c/code>가 아니라 \u003ccode>all\u003c/code>을 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">6. \u003ccode>either\u003c/code> — 둘 중 어느 하나\u003c/h2>\n\u003cp>두 자리가 모두 비어 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>You can sit in \u003cstrong>either seat\u003c/strong>.\u003cbr>두 자리 중 어느 쪽에 앉아도 된다.\u003c/p>\n\u003c/blockquote>\n\u003cp>하나를 고르는 상황이며, \u003cstrong>어느 쪽도 가능\u003c/strong>하다는 뜻이다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Either answer is\u003c/strong> acceptable.\u003cbr>두 답 중 어느 쪽도 받아들일 수 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>either + 단수명사 + 단수동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>either side of the road\u003c/code>처럼 문맥에 따라 “길 양쪽 각각”을 가리키는 용법도 있지만, 기본 선택 의미부터 잡는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">7. \u003ccode>neither\u003c/code> — 둘 다 아니다\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Neither answer is\u003c/strong> correct.\u003cbr>두 답 모두 맞지 않는다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이미 부정 의미가 있으므로 같은 의미로 \u003ccode>not\u003c/code>을 또 넣지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Neither answer isn&#39;t correct.\u003cbr>✅ Neither answer is correct.\u003c/p>\n\u003c/blockquote>\n\u003cp>비교:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>both\u003c/strong> → 둘 다 해당\u003cbr>\u003cstrong>either\u003c/strong> → 둘 중 어느 하나\u003cbr>\u003cstrong>neither\u003c/strong> → 둘 다 해당하지 않음\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">8. \u003ccode>of\u003c/code>를 쓸 때\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>each of the students\u003c/strong>\u003cbr>그 학생들 각각\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>either of these books\u003c/strong>\u003cbr>이 두 책 중 어느 하나\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>neither of them\u003c/strong>\u003cbr>그 둘 중 어느 쪽도 아님\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>of\u003c/code> 뒤에는 특정 집단을 나타내는 복수명사나 목적격 대명사가 온다.\u003c/p>\n\u003cp>격식 있는 문장에서는 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>Each of the students \u003cstrong>has\u003c/strong> a book.\u003cbr>Neither of them \u003cstrong>is\u003c/strong> ready.\u003c/p>\n\u003c/blockquote>\n\u003cp>라고 한다. 특히 \u003ccode>either/neither of + 복수\u003c/code> 뒤의 복수동사는 회화에서 흔하지만, 기본 작문에서는 단수를 기준으로 삼으면 된다.\u003c/p>\n\u003cp>\u003ccode>every\u003c/code>는 바로 \u003ccode>of\u003c/code>와 연결하지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ every of them\u003cbr>✅ \u003cstrong>every one of them\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">9. 대명사 뒤에 오는 \u003ccode>each / all / both\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>We \u003cstrong>each have\u003c/strong> a key.\u003cbr>우리는 각자 열쇠가 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 문장의 주어는 \u003ccode>each\u003c/code>가 아니라 \u003cstrong>we\u003c/strong>다. 따라서 \u003ccode>have\u003c/code>를 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>We \u003cstrong>all agree\u003c/strong>.\u003cbr>우리는 모두 동의한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They \u003cstrong>are both\u003c/strong> tired.\u003cbr>그들은 둘 다 피곤하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>단어만 보고 동사를 결정하지 말고 \u003cstrong>주어 전체\u003c/strong>를 확인한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">10. \u003ccode>not both\u003c/code>와 \u003ccode>neither\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Both answers aren&#39;t correct.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이 문장은 부정의 범위가 모호하게 느껴질 수 있다. 뜻을 분명히 하려면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Not both answers are correct.\u003c/strong>\u003cbr>두 답이 모두 맞는 것은 아니다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 적어도 하나는 틀림\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Neither answer is correct.\u003c/strong>\u003cbr>두 답이 모두 틀리다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 맞는 것이 하나도 없음\u003c/p>\n\u003cp>“모두 ~인 것은 아니다”와 “모두 ~아니다”를 구별한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">핵심\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\u003cthead>\u003ctr>\u003cth scope=\"col\">표현\u003c/th>\u003cth scope=\"col\">기본 형태\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>each / every\u003c/td>\u003ctd>단수명사 + 단수동사\u003c/td>\u003c/tr>\u003ctr>\u003ctd>all\u003c/td>\u003ctd>복수명사 또는 불가산명사에 맞춤\u003c/td>\u003c/tr>\u003ctr>\u003ctd>both\u003c/td>\u003ctd>복수명사 + 복수동사\u003c/td>\u003c/tr>\u003ctr>\u003ctd>either / neither\u003c/td>\u003ctd>단수명사 + 단수동사\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">연습\u003c/h2>\n\u003col>\n\u003cli>\u003cp>Every student \u003cstrong>has / have\u003c/strong> a ticket.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Both answers \u003cstrong>is / are\u003c/strong> correct.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>두 답 모두 틀리다. → \u003cstrong>Neither / Either\u003c/strong> answer is correct.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>We each \u003cstrong>has / have\u003c/strong> a key.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003cstrong>Every of them / Every one of them\u003c/strong> is important.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>All the water \u003cstrong>is / are\u003c/strong> gone.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>두 자리 중 어느 쪽에 앉아도 된다. → You can take \u003cstrong>either seat / both seat\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>91단계 — \u003c/strong>\u003cstrong>\u003ccode>another / other / others / the other / the others\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. each — 각각","depth":2},{"id":"reading-2","label":"2. every — 모두가 빠짐없이","depth":2},{"id":"reading-3","label":"3. 둘일 때는 each, 셋 이상에는 every","depth":2},{"id":"reading-4","label":"4. all — 전체","depth":2},{"id":"reading-5","label":"5. both — 둘 다","depth":2},{"id":"reading-6","label":"6. either — 둘 중 어느 하나","depth":2},{"id":"reading-7","label":"7. neither — 둘 다 아니다","depth":2},{"id":"reading-8","label":"8. of를 쓸 때","depth":2},{"id":"reading-9","label":"9. 대명사 뒤에 오는 each / all / both","depth":2},{"id":"reading-10","label":"10. not both와 neither","depth":2},{"id":"reading-11","label":"핵심","depth":2},{"id":"reading-12","label":"연습","depth":2}],"origin":"notion","characters":3605,"aliases":{"structure":"concept","examples":"concept","contrast":"concept","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-7","topic-8":"reading-8","topic-9":"reading-9","topic-10":"reading-10","topic-11":"reading-11","topic-12":"reading-12"}},{"id":91,"title":"91단계 — another / other / others / the other / the others","html":"\u003ch1 id=\"lesson-title\" data-id=\"91\">91단계 — another / other / others / the other / the others\u003c/h1>\n\u003cp>이번 표현들은 모두 “다른”과 관련 있다.\u003c/p>\n\u003cp>하지만 다음 두 가지를 구분해야 한다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>하나인가, 여러 개인가?\u003c/strong>\u003cbr>\u003cstrong>아무 다른 것인가, 정해진 나머지인가?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>another\u003c/code> — 다른 하나 / 하나 더\u003c/h2>\n\u003cblockquote>\n\u003cp>I&#39;d like \u003cstrong>another cup\u003c/strong> of coffee.\u003cbr>커피 한 잔 더 주세요.\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>This chair is broken. Let&#39;s find \u003cstrong>another chair\u003c/strong>.\u003cbr>이 의자는 망가졌어. 다른 의자를 찾자.\u003c/p>\n\u003c/blockquote>\n\u003cp>첫 번째는 \u003cstrong>추가\u003c/strong>, 두 번째는 \u003cstrong>대체\u003c/strong>다.\u003c/p>\n\u003cp>기본 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>another + 단수 가산명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>another\u003c/code> 안에 이미 \u003ccode>an\u003c/code>의 의미가 있으므로:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ an another book\u003cbr>✅ another book\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 명사가 분명하면 \u003ccode>another\u003c/code>만\u003c/h2>\n\u003cblockquote>\n\u003cp>This pen doesn&#39;t work. Can I have \u003cstrong>another\u003c/strong>?\u003cbr>이 펜은 안 써져요. 다른 것 하나 받을 수 있을까요?\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>another = another pen\u003c/p>\n\u003c/blockquote>\n\u003cp>앞에서 무엇을 말하는지 알기 때문에 명사를 반복하지 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>other + 명사\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>other\u003c/code>는 “다른”이라는 뜻으로 명사 앞에 온다.\u003c/p>\n\u003cblockquote>\n\u003cp>Do you have \u003cstrong>other questions\u003c/strong>?\u003cbr>다른 질문이 있나요?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We need \u003cstrong>other information\u003c/strong>.\u003cbr>다른 정보가 필요하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>복수 가산명사나 불가산명사 앞에서 관사 없이 쓸 수 있다.\u003c/p>\n\u003cp>단수 가산명사라면 한정사가 필요하다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ \u003cstrong>another book\u003c/strong>\u003cbr>✅ \u003cstrong>the other book\u003c/strong>\u003cbr>✅ \u003cstrong>my other book\u003c/strong>\u003cbr>❌ I need \u003cstrong>other book\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>others\u003c/code> — 다른 것들 / 다른 사람들\u003c/h2>\n\u003cp>\u003ccode>others\u003c/code>는 명사를 포함한 표현이다.\u003c/p>\n\u003cblockquote>\n\u003cp>Some people like tea. \u003cstrong>Others\u003c/strong> prefer coffee.\u003cbr>어떤 사람들은 차를 좋아한다. 다른 사람들은 커피를 더 좋아한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>others = other people\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서 뒤에 명사를 다시 붙이지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ others people\u003cbr>✅ other people\u003cbr>✅ others\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. \u003ccode>the other\u003c/code> — 정해진 나머지 하나\u003c/h2>\n\u003cp>펜이 두 개 있다. 하나는 빨간색, 하나는 파란색이다.\u003c/p>\n\u003cblockquote>\n\u003cp>One pen is red. \u003cstrong>The other\u003c/strong> is blue.\u003cbr>하나는 빨간색이고, 나머지 하나는 파란색이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>어떤 다른 펜이든 괜찮다는 뜻이 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>이미 정해진 두 개 중 남은 하나\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>명사를 붙여도 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>The other pen\u003c/strong> is blue.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">6. \u003ccode>another\u003c/code>와 \u003ccode>the other\u003c/code> 비교\u003c/h2>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">많은 것 중 다른 하나\u003c/h3>\n\u003cblockquote>\n\u003cp>This shirt is too small. Show me \u003cstrong>another\u003c/strong>.\u003cbr>이 셔츠는 너무 작아요. 다른 것 하나 보여주세요.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 아직 어떤 셔츠인지 정해지지 않음\u003c/p>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">두 개 중 나머지 하나\u003c/h3>\n\u003cblockquote>\n\u003cp>I tried one of the two shirts. I&#39;ll try \u003cstrong>the other\u003c/strong> now.\u003cbr>두 셔츠 중 하나를 입어 봤다. 이제 나머지 하나를 입어 볼 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 어느 셔츠인지 정해짐\u003c/p>\n\u003cp>핵심은 “다르다”보다 \u003cstrong>대상이 특정되는지\u003c/strong>다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. \u003ccode>the others\u003c/code> — 정해진 나머지 전부\u003c/h2>\n\u003cp>책 다섯 권이 있다. 두 권은 내 것이다.\u003c/p>\n\u003cblockquote>\n\u003cp>Two books are mine. \u003cstrong>The others\u003c/strong> are yours.\u003cbr>두 권은 내 것이고 나머지는 네 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 남은 \u003cstrong>세 권 전부\u003c/strong>를 말한다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>the others = the other books\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>Some books are easy. \u003cstrong>Others\u003c/strong> are difficult.\u003c/p>\n\u003c/blockquote>\n\u003cp>는 다른 책들을 말하지만, 반드시 정해진 집단의 나머지 전부라고 확정하는 표현은 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. \u003ccode>other\u003c/code>에 붙는 \u003ccode>s\u003c/code>의 위치\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\u003cthead>\u003ctr>\u003cth scope=\"col\">명사를 붙일 때\u003c/th>\u003cth scope=\"col\">명사를 반복하지 않을 때\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>other students\u003c/td>\u003ctd>others\u003c/td>\u003c/tr>\u003ctr>\u003ctd>the other students\u003c/td>\u003ctd>the others\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\n\u003cblockquote>\n\u003cp>❌ the others students\u003cbr>✅ the other students\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>other\u003c/code>가 명사를 꾸미면 그 명사에 복수형을 표시한다. \u003ccode>others\u003c/code>는 이미 “다른 사람들/것들”을 대신한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">9. \u003ccode>another + 숫자 + 복수명사\u003c/code>\u003c/h2>\n\u003cp>기본은 \u003ccode>another + 단수명사\u003c/code>지만 이런 표현도 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>We need \u003cstrong>another two days\u003c/strong>.\u003cbr>우리는 이틀이 더 필요하다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;ll stay for \u003cstrong>another ten minutes\u003c/strong>.\u003cbr>나는 10분 더 머물겠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>two days / ten minutes\u003c/code>라는 \u003cstrong>추가 수량 덩어리\u003c/strong>를 말한다.\u003c/p>\n\u003cp>따라서 “another 다음에는 절대로 복수가 올 수 없다”는 규칙은 정확하지 않다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">10. 자주 쓰는 묶음\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>one ... the other ...\u003c/strong>\u003cbr>하나는 …, 나머지 하나는 …\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>some ... others ...\u003c/strong>\u003cbr>어떤 이들은 …, 다른 이들은 …\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>some ... the others ...\u003c/strong>\u003cbr>일부는 …, 정해진 나머지 전부는 …\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I have two sisters. One lives in Seoul; the other lives in Busan.\u003cbr>자매가 두 명 있다. 한 명은 서울에, 다른 한 명은 부산에 산다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">핵심\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>another = 다른 하나 / 하나 더\u003c/strong>\u003cbr>\u003cstrong>other + 명사 = 다른 ~\u003c/strong>\u003cbr>\u003cstrong>others = 다른 사람들·것들\u003c/strong>\u003cbr>\u003cstrong>the other = 정해진 나머지 하나\u003c/strong>\u003cbr>\u003cstrong>the others = 정해진 나머지 전부\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">연습\u003c/h2>\n\u003col>\n\u003cli>\u003cp>커피 한 잔 더 → \u003cstrong>another cup / other cup\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Do you have \u003cstrong>other questions / others questions\u003c/strong>?\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Some people walked. \u003cstrong>Others / Other\u003c/strong> took a bus.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>두 개 중 나머지 하나 → \u003cstrong>another / the other\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>열 명 중 두 명은 떠났고 나머지 여덟 명은 남았다.\u003c/p>\n\u003cp> → Two left. \u003cstrong>The others / Another\u003c/strong> stayed.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>We need \u003cstrong>another two days / others two days\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003cstrong>The other students / The others students\u003c/strong> are waiting.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>92단계 — 재귀대명사\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. another — 다른 하나 / 하나 더","depth":2},{"id":"reading-2","label":"2. 명사가 분명하면 another만","depth":2},{"id":"reading-3","label":"3. other + 명사","depth":2},{"id":"reading-4","label":"4. others — 다른 것들 / 다른 사람들","depth":2},{"id":"reading-5","label":"5. the other — 정해진 나머지 하나","depth":2},{"id":"reading-6","label":"6. another와 the other 비교","depth":2},{"id":"reading-7","label":"많은 것 중 다른 하나","depth":3},{"id":"reading-8","label":"두 개 중 나머지 하나","depth":3},{"id":"reading-9","label":"7. the others — 정해진 나머지 전부","depth":2},{"id":"reading-10","label":"8. other에 붙는 s의 위치","depth":2},{"id":"reading-11","label":"9. another + 숫자 + 복수명사","depth":2},{"id":"reading-12","label":"10. 자주 쓰는 묶음","depth":2},{"id":"reading-13","label":"핵심","depth":2},{"id":"reading-14","label":"연습","depth":2}],"origin":"notion","characters":3489,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-6","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-12","topic-11":"reading-13","topic-12":"reading-14"}},{"id":92,"title":"92단계 — 재귀대명사 myself / yourself / himself ...","html":"\u003ch1 id=\"lesson-title\" data-id=\"92\">92단계 — 재귀대명사 myself / yourself / himself ...\u003c/h1>\n\u003cp>이번에는 \u003cstrong>행동이 주어 자신에게 돌아오는 경우\u003c/strong>를 배운다.\u003c/p>\n\u003cblockquote>\n\u003cp>I hurt \u003cstrong>myself\u003c/strong>.\u003cbr>나는 다쳤다 / 나 자신을 다치게 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>행동하는 사람도 \u003ccode>I\u003c/code>, 다친 사람도 \u003ccode>I\u003c/code>다.\u003c/p>\n\u003cp>이처럼 “자기 자신”을 나타내는 말을 \u003cstrong>재귀대명사\u003c/strong>라고 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 형태부터 보기\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\u003cthead>\u003ctr>\u003cth scope=\"col\">주어\u003c/th>\u003cth scope=\"col\">재귀대명사\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>I\u003c/td>\u003ctd>myself\u003c/td>\u003c/tr>\u003ctr>\u003ctd>you 한 명\u003c/td>\u003ctd>yourself\u003c/td>\u003c/tr>\u003ctr>\u003ctd>he\u003c/td>\u003ctd>himself\u003c/td>\u003c/tr>\u003ctr>\u003ctd>she\u003c/td>\u003ctd>herself\u003c/td>\u003c/tr>\u003ctr>\u003ctd>it\u003c/td>\u003ctd>itself\u003c/td>\u003c/tr>\u003ctr>\u003ctd>we\u003c/td>\u003ctd>ourselves\u003c/td>\u003c/tr>\u003ctr>\u003ctd>you 여러 명\u003c/td>\u003ctd>yourselves\u003c/td>\u003c/tr>\u003ctr>\u003ctd>they\u003c/td>\u003ctd>themselves\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\n\u003cp>단수에서는 주로 \u003ccode>-self\u003c/code>, 복수에서는 \u003ccode>-selves\u003c/code>로 끝난다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ ourself\u003cbr>✅ ourselves\u003c/p>\n\u003c/blockquote>\n\u003cp>단수의 \u003ccode>they\u003c/code>를 쓰는 사람도 \u003ccode>themselves\u003c/code>를 사용할 수 있다. 여기서는 기본 인칭 대응부터 익힌다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 주어와 목적어가 같은 사람\u003c/h2>\n\u003cblockquote>\n\u003cp>Mina looked at \u003cstrong>herself\u003c/strong> in the mirror.\u003cbr>미나는 거울 속 자기 자신을 보았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>누가 보았나?\u003c/p>\n\u003cblockquote>\n\u003cp>Mina\u003c/p>\n\u003c/blockquote>\n\u003cp>누구를 보았나?\u003c/p>\n\u003cblockquote>\n\u003cp>Mina 자신\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서 \u003ccode>herself\u003c/code>다.\u003c/p>\n\u003cblockquote>\n\u003cp>He cut \u003cstrong>himself\u003c/strong> while cooking.\u003cbr>그는 요리하다가 자기 몸을 베었다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>her\u003c/code>와 \u003ccode>herself\u003c/code>는 다르다\u003c/h2>\n\u003cblockquote>\n\u003cp>Mina looked at \u003cstrong>her\u003c/strong>.\u003cbr>미나는 그녀를 보았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 보통 다른 여성을 가리킴\u003c/p>\n\u003cblockquote>\n\u003cp>Mina looked at \u003cstrong>herself\u003c/strong>.\u003cbr>미나는 자기 자신을 보았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 미나 자신을 가리킴\u003c/p>\n\u003cp>같은 사람을 뜻하려고 일반 목적격을 무조건 쓰면 안 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>I taught \u003cstrong>myself\u003c/strong> English.\u003cbr>나는 영어를 독학했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>myself\u003c/code>는 가르침을 받은 사람도 나라는 뜻이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. 주어를 대신해서 아무 데나 쓰지 않는다\u003c/h2>\n\u003cblockquote>\n\u003cp>❌ Myself sent the email.\u003cbr>✅ I sent the email.\u003c/p>\n\u003c/blockquote>\n\u003cp>재귀대명사는 보통 혼자 주어 자리를 맡는 말이 아니다.\u003c/p>\n\u003cp>두 사람을 묶을 때도:\u003c/p>\n\u003cblockquote>\n\u003cp>Mina and \u003cstrong>I\u003c/strong> prepared the report.\u003cbr>미나와 내가 보고서를 준비했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>격식을 차린다는 이유로 \u003ccode>I / me\u003c/code> 대신 \u003ccode>myself\u003c/code>를 넣지 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. 강조: 바로 내가 직접\u003c/h2>\n\u003cblockquote>\n\u003cp>I made this cake \u003cstrong>myself\u003c/strong>.\u003cbr>내가 이 케이크를 직접 만들었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 문장에서 \u003ccode>myself\u003c/code>를 빼도:\u003c/p>\n\u003cblockquote>\n\u003cp>I made this cake.\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 완전한 문장이 된다.\u003c/p>\n\u003cp>즉, 여기서는 필수 목적어가 아니라 \u003cstrong>주어를 강조\u003c/strong>한다.\u003c/p>\n\u003cblockquote>\n\u003cp>The director \u003cstrong>herself\u003c/strong> answered the phone.\u003cbr>감독이 직접 전화를 받았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>“다른 사람이 대신한 것이 아니다”라는 느낌이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">6. 목적어와 강조 용법 구별\u003c/h2>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">필수 의미에 참여\u003c/h3>\n\u003cblockquote>\n\u003cp>She blamed \u003cstrong>herself\u003c/strong>.\u003cbr>그녀는 자기 자신을 탓했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>herself\u003c/code>는 누구를 탓했는지 말한다.\u003c/p>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">강조\u003c/h3>\n\u003cblockquote>\n\u003cp>She wrote the letter \u003cstrong>herself\u003c/strong>.\u003cbr>그녀가 직접 편지를 썼다.\u003c/p>\n\u003c/blockquote>\n\u003cp>목적어는 이미 \u003ccode>the letter\u003c/code>다. \u003ccode>herself\u003c/code>는 직접 했다는 뜻을 보탠다.\u003c/p>\n\u003cp>같은 형태라도 문장에서 하는 일이 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. \u003ccode>by oneself\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>I live \u003cstrong>by myself\u003c/strong>.\u003cbr>나는 혼자 산다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She fixed it \u003cstrong>by herself\u003c/strong>.\u003cbr>그녀는 도움 없이 혼자 그것을 고쳤다.\u003c/p>\n\u003c/blockquote>\n\u003cp>문맥에 따라:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>혼자 / 다른 사람의 도움 없이\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이다.\u003c/p>\n\u003cp>비교:\u003c/p>\n\u003cblockquote>\n\u003cp>I did it \u003cstrong>myself\u003c/strong>. → 내가 직접 했다.\u003cbr>I did it \u003cstrong>by myself\u003c/strong>. → 도움 없이 혼자 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>첫 번째가 언제나 “아무 도움도 받지 않았다”까지 뜻하는 것은 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. 자주 쓰는 표현\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Enjoy yourself!\u003c/strong>\u003cbr>즐겁게 보내!\u003c/p>\n\u003c/blockquote>\n\u003cp>여러 명에게는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Enjoy yourselves!\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Help yourself\u003c/strong> to some cake.\u003cbr>케이크 좀 편하게 드세요.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Make \u003cstrong>yourself\u003c/strong> at home.\u003cbr>편하게 계세요.\u003c/p>\n\u003c/blockquote>\n\u003cp>단어별 직역보다 표현 전체의 쓰임을 기억한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">9. 한국어의 “자신”을 모두 옮기지는 않는다\u003c/h2>\n\u003cp>일상적인 몸 관리 행동에서는 목적어가 분명하면 생략하는 경우가 많다.\u003c/p>\n\u003cblockquote>\n\u003cp>I washed and got dressed.\u003cbr>나는 씻고 옷을 입었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>꼭 \u003ccode>washed myself\u003c/code>라고 해야 하는 것은 아니다. 스스로 씻을 수 있다는 점을 강조하는 문맥에서는 \u003ccode>myself\u003c/code>가 의미를 더할 수 있다.\u003c/p>\n\u003cp>위치를 나타내는 전치사 뒤에서도:\u003c/p>\n\u003cblockquote>\n\u003cp>She put the bag beside \u003cstrong>her\u003c/strong>.\u003cbr>그녀는 가방을 자기 옆에 놓았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 일반 목적격이 자연스러운 경우가 있다. \u003cstrong>주어와 관련되면 전부 재귀형\u003c/strong>이라는 규칙은 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">핵심\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 자신이 행동의 대상 → 재귀대명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She hurt \u003cstrong>herself\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>직접 했다는 강조 → 재귀대명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She made it \u003cstrong>herself\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>혼자 / 도움 없이 → by + 재귀대명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">연습\u003c/h2>\n\u003col>\n\u003cli>\u003cp>He looked at \u003cstrong>himself / herself\u003c/strong> in the mirror.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>We introduced \u003cstrong>ourselves / ourself\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>내가 직접 만들었다. → I made it \u003cstrong>myself / me\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003cstrong>I / Myself\u003c/strong> sent the message.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>여러 명에게 “즐겁게 보내세요!” → Enjoy \u003cstrong>yourself / yourselves\u003c/strong>!\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>다른 사람 도움 없이 고쳤다. → She fixed it \u003cstrong>by herself / by her\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Mina blamed \u003cstrong>herself / himself\u003c/strong> for the mistake.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>93단계 — \u003c/strong>\u003cstrong>\u003ccode>each other / one another\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 형태부터 보기","depth":2},{"id":"reading-2","label":"2. 주어와 목적어가 같은 사람","depth":2},{"id":"reading-3","label":"3. her와 herself는 다르다","depth":2},{"id":"reading-4","label":"4. 주어를 대신해서 아무 데나 쓰지 않는다","depth":2},{"id":"reading-5","label":"5. 강조: 바로 내가 직접","depth":2},{"id":"reading-6","label":"6. 목적어와 강조 용법 구별","depth":2},{"id":"reading-7","label":"필수 의미에 참여","depth":3},{"id":"reading-8","label":"강조","depth":3},{"id":"reading-9","label":"7. by oneself","depth":2},{"id":"reading-10","label":"8. 자주 쓰는 표현","depth":2},{"id":"reading-11","label":"9. 한국어의 “자신”을 모두 옮기지는 않는다","depth":2},{"id":"reading-12","label":"핵심","depth":2},{"id":"reading-13","label":"연습","depth":2}],"origin":"notion","characters":3316,"aliases":{"structure":"reading-1","examples":"concept","contrast":"concept","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-12","topic-11":"reading-13","topic-12":"concept"}},{"id":93,"title":"93단계 — 상호대명사 each other / one another","html":"\u003ch1 id=\"lesson-title\" data-id=\"93\">93단계 — 상호대명사 each other / one another\u003c/h1>\n\u003cp>지난 단계에서:\u003c/p>\n\u003cblockquote>\n\u003cp>They looked at \u003cstrong>themselves\u003c/strong>.\u003cbr>그들은 자기 자신들을 보았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>를 배웠다.\u003c/p>\n\u003cp>이번에는:\u003c/p>\n\u003cblockquote>\n\u003cp>They looked at \u003cstrong>each other\u003c/strong>.\u003cbr>그들은 서로를 보았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 \u003cstrong>행동이 서로에게 향하는 관계\u003c/strong>를 배운다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>each other\u003c/code> — 서로\u003c/h2>\n\u003cp>미나가 준을 돕고, 준이 미나를 돕는다.\u003c/p>\n\u003cblockquote>\n\u003cp>Mina helps Jun.\u003cbr>Jun helps Mina.\u003c/p>\n\u003c/blockquote>\n\u003cp>한 문장으로:\u003c/p>\n\u003cblockquote>\n\u003cp>They help \u003cstrong>each other\u003c/strong>.\u003cbr>그들은 서로 돕는다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>each other\u003c/code>는 이 문장에서 목적어다.\u003c/p>\n\u003cblockquote>\n\u003cp>주어: They\u003cbr>동사: help\u003cbr>목적어: each other\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>one another\u003c/code>도 비슷하다\u003c/h2>\n\u003cblockquote>\n\u003cp>The team members support \u003cstrong>one another\u003c/strong>.\u003cbr>팀원들은 서로를 지지한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>The team members support \u003cstrong>each other\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>두 문장 모두 자연스럽다.\u003c/p>\n\u003cp>전통적으로 \u003ccode>each other\u003c/code>는 둘, \u003ccode>one another\u003c/code>는 셋 이상이라고 구분하기도 했지만, \u003cstrong>현대 영어에서는 둘이 많이 겹친다.\u003c/strong>\u003c/p>\n\u003cp>사람이 셋 이상이라는 이유만으로 \u003ccode>each other\u003c/code>를 틀렸다고 하면 안 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>themselves\u003c/code>와 차이\u003c/h2>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">자신에게 향함\u003c/h3>\n\u003cblockquote>\n\u003cp>They blamed \u003cstrong>themselves\u003c/strong>.\u003cbr>그들은 자기 자신들을 탓했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 각자가 자기 잘못이라고 생각함\u003c/p>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">상대에게 향함\u003c/h3>\n\u003cblockquote>\n\u003cp>They blamed \u003cstrong>each other\u003c/strong>.\u003cbr>그들은 서로를 탓했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 상대방의 잘못이라고 생각함\u003c/p>\n\u003cp>형태가 아니라 \u003cstrong>화살표의 방향\u003c/strong>을 생각하면 쉽다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>themselves → 자신\u003c/strong>\u003cbr>\u003cstrong>each other → 상대방\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 전치사 뒤에도 사용\u003c/h2>\n\u003cblockquote>\n\u003cp>We talked \u003cstrong>to each other\u003c/strong>.\u003cbr>우리는 서로 이야기했다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They smiled \u003cstrong>at each other\u003c/strong>.\u003cbr>그들은 서로를 보며 미소 지었다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We learned \u003cstrong>from one another\u003c/strong>.\u003cbr>우리는 서로에게서 배웠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>원래 동사와 함께 쓰는 전치사를 유지한다.\u003c/p>\n\u003cblockquote>\n\u003cp>talk \u003cstrong>to\u003c/strong> someone → talk \u003cstrong>to each other\u003c/strong>\u003cbr>look \u003cstrong>at\u003c/strong> someone → look \u003cstrong>at each other\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ They looked each other.\u003cbr>✅ They looked \u003cstrong>at\u003c/strong> each other.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. 주어는 관계에 참여하는 사람들을 포함한다\u003c/h2>\n\u003cblockquote>\n\u003cp>Mina and I understand \u003cstrong>each other\u003c/strong>.\u003cbr>미나와 나는 서로를 이해한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>Mina and I\u003c/code>라는 둘 이상의 대상이 있어야 서로 이해할 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I understand each other.\u003cbr>✅ We understand each other.\u003c/p>\n\u003c/blockquote>\n\u003cp>집단을 나타내는 명사는 여러 구성원을 포함할 수 있지만, 기초 작문에서는 \u003ccode>we / they / A and B\u003c/code>처럼 관계가 분명한 주어로 연습한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. 소유형: \u003ccode>each other&#39;s\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>We know \u003cstrong>each other&#39;s names\u003c/strong>.\u003cbr>우리는 서로의 이름을 안다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They borrowed \u003cstrong>each other&#39;s books\u003c/strong>.\u003cbr>그들은 서로의 책을 빌렸다.\u003c/p>\n\u003c/blockquote>\n\u003cp>소유를 나타내려면 \u003cstrong>each other 뒤에 &#39;s\u003c/strong>를 붙인다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ each \u003cstrong>other&#39;s\u003c/strong> names\u003cbr>❌ each \u003cstrong>others&#39;\u003c/strong> names\u003cbr>❌ each \u003cstrong>others\u003c/strong> names\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>one another\u003c/code>도 같다.\u003c/p>\n\u003cblockquote>\n\u003cp>one \u003cstrong>another&#39;s\u003c/strong> ideas\u003cbr>서로의 생각\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. 뒤의 명사는 상황에 따라 단수·복수\u003c/h2>\n\u003cblockquote>\n\u003cp>We visited \u003cstrong>each other&#39;s homes\u003c/strong>.\u003cbr>우리는 서로의 집을 방문했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>서로 다른 집들이 있으므로 복수가 자연스럽다.\u003c/p>\n\u003cblockquote>\n\u003cp>They held \u003cstrong>each other&#39;s hand\u003c/strong>.\u003cbr>그들은 서로의 손을 잡았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>각자가 상대의 한 손을 잡는 장면이라면 단수도 가능하다. \u003ccode>hands\u003c/code>도 자연스럽게 쓴다.\u003c/p>\n\u003cp>소유형 뒤에 무조건 단수나 복수를 붙인다고 외우지 않고 \u003cstrong>실제로 무엇을 몇 개 말하는지\u003c/strong>를 본다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. \u003ccode>together\u003c/code>와 같지 않다\u003c/h2>\n\u003cblockquote>\n\u003cp>We studied \u003cstrong>together\u003c/strong>.\u003cbr>우리는 함께 공부했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 같은 활동을 함께 함\u003c/p>\n\u003cblockquote>\n\u003cp>We helped \u003cstrong>each other\u003c/strong>.\u003cbr>우리는 서로 도왔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 도움의 대상이 상대방임\u003c/p>\n\u003cblockquote>\n\u003cp>We cooked together.\u003c/p>\n\u003c/blockquote>\n\u003cp>는 함께 요리했다는 뜻이다. \u003ccode>We cooked each other.\u003c/code>라고 하면 서로를 요리했다는 전혀 다른 이상한 뜻이 된다.\u003c/p>\n\u003cp>\u003cstrong>함께\u003c/strong>와 \u003cstrong>서로를\u003c/strong>는 구분해야 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">9. 생활에서 자주 쓰는 문장\u003c/h2>\n\u003cblockquote>\n\u003cp>We see \u003cstrong>each other\u003c/strong> every weekend.\u003cbr>우리는 주말마다 만난다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They don&#39;t know \u003cstrong>each other\u003c/strong> very well.\u003cbr>그들은 서로를 잘 알지 못한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Let&#39;s listen \u003cstrong>to each other\u003c/strong>.\u003cbr>서로의 말에 귀를 기울이자.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We should respect \u003cstrong>one another&#39;s opinions\u003c/strong>.\u003cbr>우리는 서로의 의견을 존중해야 한다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">핵심\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>each other / one another = 서로\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>themselves = 자기 자신들\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>소유형은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>each other&#39;s / one another&#39;s\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고 전치사가 필요한 동사라면 그 전치사도 유지한다.\u003c/p>\n\u003cblockquote>\n\u003cp>talk \u003cstrong>to\u003c/strong> each other\u003cbr>look \u003cstrong>at\u003c/strong> each other\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">연습\u003c/h2>\n\u003col>\n\u003cli>\u003cp>서로 돕는다. → They help \u003cstrong>each other / themselves\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>거울에서 각자 자기 모습을 본다. → They look at \u003cstrong>themselves / each other\u003c/strong> in the mirror.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>We talked \u003cstrong>to each other / each other\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>서로의 이름 → \u003cstrong>each other&#39;s names / each others&#39; names\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>함께 공부했다. → We studied \u003cstrong>together / each other\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>The team members support \u003cstrong>one another / one another&#39;s\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Let&#39;s listen \u003cstrong>to each other / at each other\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>94단계 — 부가의문문\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. each other — 서로","depth":2},{"id":"reading-2","label":"2. one another도 비슷하다","depth":2},{"id":"reading-3","label":"3. themselves와 차이","depth":2},{"id":"reading-4","label":"자신에게 향함","depth":3},{"id":"reading-5","label":"상대에게 향함","depth":3},{"id":"reading-6","label":"4. 전치사 뒤에도 사용","depth":2},{"id":"reading-7","label":"5. 주어는 관계에 참여하는 사람들을 포함한다","depth":2},{"id":"reading-8","label":"6. 소유형: each other's","depth":2},{"id":"reading-9","label":"7. 뒤의 명사는 상황에 따라 단수·복수","depth":2},{"id":"reading-10","label":"8. together와 같지 않다","depth":2},{"id":"reading-11","label":"9. 생활에서 자주 쓰는 문장","depth":2},{"id":"reading-12","label":"핵심","depth":2},{"id":"reading-13","label":"연습","depth":2}],"origin":"notion","characters":3326,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-3","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-12","topic-11":"reading-13","topic-12":"concept"}},{"id":94,"title":"94단계 — 부가의문문 Question Tags","html":"\u003ch1 id=\"lesson-title\" data-id=\"94\">94단계 — 부가의문문 Question Tags\u003c/h1>\n\u003cp>이번에는 문장 뒤에 짧은 질문을 붙인다.\u003c/p>\n\u003cblockquote>\n\u003cp>You&#39;re tired, \u003cstrong>aren&#39;t you\u003c/strong>?\u003cbr>너 피곤하지, 그렇지?\u003c/p>\n\u003c/blockquote>\n\u003cp>완전히 새 정보를 묻기도 하지만, 보통 \u003cstrong>내 생각이 맞는지 확인하거나 상대의 동의를 구할 때\u003c/strong> 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 원리\u003c/h2>\n\u003cp>가장 흔한 형태는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>긍정문 + 부정 tag\u003c/strong>\u003cbr>\u003cstrong>부정문 + 긍정 tag\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She is here, \u003cstrong>isn&#39;t she\u003c/strong>?\u003cbr>그녀 여기 있지, 그렇지?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She isn&#39;t here, \u003cstrong>is she\u003c/strong>?\u003cbr>그녀 여기 없지, 그렇지?\u003c/p>\n\u003c/blockquote>\n\u003cp>tag의 어순은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>조동사 또는 be동사 + 대명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. be동사가 있으면 그대로\u003c/h2>\n\u003cblockquote>\n\u003cp>He \u003cstrong>is\u003c/strong> a doctor, \u003cstrong>isn&#39;t he\u003c/strong>?\u003cbr>그는 의사지, 그렇지?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They \u003cstrong>were\u003c/strong> busy, \u003cstrong>weren&#39;t they\u003c/strong>?\u003cbr>그들은 바빴지, 그렇지?\u003c/p>\n\u003c/blockquote>\n\u003cp>시제도 맞춘다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ She was tired, isn&#39;t she?\u003cbr>✅ She was tired, \u003cstrong>wasn&#39;t she\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 조동사가 있으면 그 조동사\u003c/h2>\n\u003cblockquote>\n\u003cp>You \u003cstrong>can\u003c/strong> swim, \u003cstrong>can&#39;t you\u003c/strong>?\u003cbr>너 수영할 수 있지?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He \u003cstrong>won&#39;t\u003c/strong> come, \u003cstrong>will he\u003c/strong>?\u003cbr>그는 안 오겠지?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We \u003cstrong>should\u003c/strong> leave, \u003cstrong>shouldn&#39;t we\u003c/strong>?\u003cbr>우리 떠나는 게 좋겠지?\u003c/p>\n\u003c/blockquote>\n\u003cp>현재완료에서도 조동사 \u003ccode>have / has\u003c/code>를 사용한다.\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>has finished\u003c/strong>, \u003cstrong>hasn&#39;t she\u003c/strong>?\u003cbr>그녀는 다 끝냈지?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. 일반동사만 있으면 \u003ccode>do / does / did\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>You like coffee, \u003cstrong>don&#39;t you\u003c/strong>?\u003cbr>너 커피 좋아하지?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Mina lives here, \u003cstrong>doesn&#39;t she\u003c/strong>?\u003cbr>미나 여기 살지?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They left early, \u003cstrong>didn&#39;t they\u003c/strong>?\u003cbr>그들은 일찍 떠났지?\u003c/p>\n\u003c/blockquote>\n\u003cp>원래 문장의 \u003cstrong>시제와 주어\u003c/strong>를 확인한다.\u003c/p>\n\u003cblockquote>\n\u003cp>현재 I/you/we/they → do\u003cbr>현재 he/she/it → does\u003cbr>과거 → did\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. tag의 주어는 대명사\u003c/h2>\n\u003cblockquote>\n\u003cp>Mina is ready, \u003cstrong>isn&#39;t she\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>Mina\u003c/code>를 반복하지 않고 \u003ccode>she\u003c/code>로 받는다.\u003c/p>\n\u003cblockquote>\n\u003cp>These books are yours, \u003cstrong>aren&#39;t they\u003c/strong>?\u003cbr>이 책들 네 것이지?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>This is yours, \u003cstrong>isn&#39;t it\u003c/strong>?\u003cbr>이거 네 것이지?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>this / that\u003c/code>은 보통 \u003ccode>it\u003c/code>, \u003ccode>these / those\u003c/code>는 \u003ccode>they\u003c/code>로 받는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">6. \u003ccode>I am\u003c/code>의 특별한 형태\u003c/h2>\n\u003cblockquote>\n\u003cp>I&#39;m late, \u003cstrong>aren&#39;t I\u003c/strong>?\u003cbr>나 늦었지?\u003c/p>\n\u003c/blockquote>\n\u003cp>일반적인 축약 tag는 \u003ccode>amn&#39;t I\u003c/code>가 아니라 \u003cstrong>aren&#39;t I\u003c/strong>다.\u003c/p>\n\u003cp>부정문에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m not late, \u003cstrong>am I\u003c/strong>?\u003cbr>나 안 늦었지?\u003c/p>\n\u003c/blockquote>\n\u003cp>라고 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">7. 부정어가 있으면 긍정 tag\u003c/h2>\n\u003cp>\u003ccode>not\u003c/code>이 없어도 \u003ccode>never / hardly / nobody\u003c/code>처럼 부정 의미가 있을 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>You \u003cstrong>never\u003c/strong> call, \u003cstrong>do you\u003c/strong>?\u003cbr>넌 전혀 전화하지 않지?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Nobody\u003c/strong> called, \u003cstrong>did they\u003c/strong>?\u003cbr>아무도 전화 안 했지?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>nobody / someone / everyone\u003c/code>처럼 사람을 가리키는 말은 tag에서 흔히 \u003cstrong>they\u003c/strong>로 받는다.\u003c/p>\n\u003cblockquote>\n\u003cp>Everyone is ready, \u003cstrong>aren&#39;t they\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>앞 문장의 \u003ccode>is\u003c/code>만 기계적으로 복사하지 않고 tag의 대명사에도 맞춘다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">8. \u003ccode>there is\u003c/code>와 명령문\u003c/h2>\n\u003cblockquote>\n\u003cp>There&#39;s a problem, \u003cstrong>isn&#39;t there\u003c/strong>?\u003cbr>문제가 있지?\u003c/p>\n\u003c/blockquote>\n\u003cp>존재를 나타내는 \u003ccode>there\u003c/code>는 tag에서도 유지한다.\u003c/p>\n\u003cp>부탁·명령에는 흔히:\u003c/p>\n\u003cblockquote>\n\u003cp>Close the door, \u003cstrong>will you\u003c/strong>?\u003cbr>문 좀 닫아 줄래?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>Let&#39;s\u003c/code>로 제안하면:\u003c/p>\n\u003cblockquote>\n\u003cp>Let&#39;s go, \u003cstrong>shall we\u003c/strong>?\u003cbr>우리 가자, 어때?\u003c/p>\n\u003c/blockquote>\n\u003cp>이런 형태는 기본 긍정·부정 전환만으로 설명하지 않고 묶어서 익힌다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">9. 억양에 따른 느낌\u003c/h2>\n\u003cp>tag 끝을 올리면 \u003cstrong>정말 확실하지 않아서 묻는 느낌\u003c/strong>이 강하다.\u003c/p>\n\u003cblockquote>\n\u003cp>You&#39;re coming, aren&#39;t you? ↗\u003c/p>\n\u003c/blockquote>\n\u003cp>끝을 내리면 \u003cstrong>맞다고 생각하면서 동의를 구하는 느낌\u003c/strong>이 강하다.\u003c/p>\n\u003cblockquote>\n\u003cp>It&#39;s a beautiful day, isn&#39;t it? ↘\u003c/p>\n\u003c/blockquote>\n\u003cp>문맥과 말투에 따라 느낌은 달라진다. 부가의문문은 문법 형태뿐 아니라 대화의 태도도 전달한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">10. 대답은 실제 사실을 기준으로\u003c/h2>\n\u003cblockquote>\n\u003cp>You don&#39;t drink coffee, do you?\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로 마신다면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Yes, I do.\u003c/strong>\u003cbr>아니, 나 마셔.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로 마시지 않는다면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>No, I don&#39;t.\u003c/strong>\u003cbr>응, 안 마셔.\u003c/p>\n\u003c/blockquote>\n\u003cp>영어의 \u003ccode>yes / no\u003c/code>는 한국어 “네 생각이 맞다/틀리다”와 일대일로 대응하지 않는다. \u003cstrong>긍정 사실이면 Yes, 부정 사실이면 No\u003c/strong>로 이해한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">핵심\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>앞 문장의 긍정·부정, 조동사·시제, 주어를 확인한다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You like it, \u003cstrong>don&#39;t you\u003c/strong>?\u003cbr>You don&#39;t like it, \u003cstrong>do you\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">연습\u003c/h2>\n\u003col>\n\u003cli>\u003cp>She&#39;s ready, \u003cstrong>isn&#39;t she / doesn&#39;t she\u003c/strong>?\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>They left, \u003cstrong>didn&#39;t they / don&#39;t they\u003c/strong>?\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>You can&#39;t drive, \u003cstrong>can you / can&#39;t you\u003c/strong>?\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I&#39;m right, \u003cstrong>aren&#39;t I / isn&#39;t I\u003c/strong>?\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Nobody came, \u003cstrong>did they / didn&#39;t they\u003c/strong>?\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Let&#39;s start, \u003cstrong>shall we / do we\u003c/strong>?\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“You don&#39;t like tea, do you?”에 실제로 차를 좋아한다고 답한다.\u003c/p>\n\u003cp> → \u003cstrong>Yes, I do. / No, I don&#39;t.\u003c/strong>\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>95단계 — 부정의문문\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 원리","depth":2},{"id":"reading-2","label":"2. be동사가 있으면 그대로","depth":2},{"id":"reading-3","label":"3. 조동사가 있으면 그 조동사","depth":2},{"id":"reading-4","label":"4. 일반동사만 있으면 do / does / did","depth":2},{"id":"reading-5","label":"5. tag의 주어는 대명사","depth":2},{"id":"reading-6","label":"6. I am의 특별한 형태","depth":2},{"id":"reading-7","label":"7. 부정어가 있으면 긍정 tag","depth":2},{"id":"reading-8","label":"8. there is와 명령문","depth":2},{"id":"reading-9","label":"9. 억양에 따른 느낌","depth":2},{"id":"reading-10","label":"10. 대답은 실제 사실을 기준으로","depth":2},{"id":"reading-11","label":"핵심","depth":2},{"id":"reading-12","label":"연습","depth":2}],"origin":"notion","characters":3020,"aliases":{"structure":"reading-6","examples":"concept","contrast":"concept","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-7","topic-8":"reading-8","topic-9":"reading-9","topic-10":"reading-10","topic-11":"reading-11","topic-12":"reading-12"}},{"id":95,"title":"95단계 — 부정의문문 Negative Questions","html":"\u003ch1 id=\"lesson-title\" data-id=\"95\">95단계 — 부정의문문 Negative Questions\u003c/h1>\n\u003cp>이번에는 질문 안에 \u003cstrong>not\u003c/strong>이 들어가는 형태를 배운다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Don&#39;t you like coffee?\u003c/strong>\u003cbr>너 커피 좋아하지 않아?\u003c/p>\n\u003c/blockquote>\n\u003cp>단순히 “안 좋아하는가?”라는 정보만 묻는 것이 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>좋아할 거라고 생각했는데, 아닌가?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 기대·놀람·확인을 함께 나타내기도 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 보통 의문문과 비교\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">일반 의문문\u003c/h3>\n\u003cblockquote>\n\u003cp>Do you live here?\u003cbr>여기 사세요?\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 거주 여부를 비교적 중립적으로 물음\u003c/p>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">부정의문문\u003c/h3>\n\u003cblockquote>\n\u003cp>Don&#39;t you live here?\u003cbr>여기 사시는 거 아니었나요?\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 여기 산다고 생각했는데 확인함\u003c/p>\n\u003cp>말투에 따라 놀람이나 의문이 더 강해질 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. be동사로 만들기\u003c/h2>\n\u003cblockquote>\n\u003cp>She is ready.\u003c/p>\n\u003c/blockquote>\n\u003cp>의문문:\u003c/p>\n\u003cblockquote>\n\u003cp>Is she ready?\u003c/p>\n\u003c/blockquote>\n\u003cp>부정의문문:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Isn&#39;t she ready?\u003c/strong>\u003cbr>그녀 아직 준비 안 됐어?\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Isn&#39;t / Aren&#39;t / Wasn&#39;t / Weren&#39;t + 주어 + …?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Aren&#39;t you tired?\u003c/strong>\u003cbr>너 안 피곤해?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Wasn&#39;t it expensive?\u003c/strong>\u003cbr>그거 비싸지 않았어?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 일반동사로 만들기\u003c/h2>\n\u003cp>현재:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Don&#39;t you know\u003c/strong> him?\u003cbr>너 그 사람 몰라?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Doesn&#39;t Mina work\u003c/strong> here?\u003cbr>미나 여기서 일하지 않아?\u003c/p>\n\u003c/blockquote>\n\u003cp>과거:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Didn&#39;t you call\u003c/strong> her?\u003cbr>너 그녀에게 전화하지 않았어?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>doesn&#39;t / didn&#39;t\u003c/code> 뒤에는 동사원형이다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Didn&#39;t you \u003cstrong>called\u003c/strong>?\u003cbr>✅ Didn&#39;t you \u003cstrong>call\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 조동사도 같은 방식\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Can&#39;t you swim?\u003c/strong>\u003cbr>너 수영 못 해?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Haven&#39;t we met before?\u003c/strong>\u003cbr>우리 전에 만난 적 있지 않나요?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Shouldn&#39;t we leave now?\u003c/strong>\u003cbr>우리 이제 떠나야 하지 않을까?\u003c/p>\n\u003c/blockquote>\n\u003cp>마지막 문장은 단순 확인을 넘어 \u003cstrong>떠나자는 제안\u003c/strong>의 느낌도 낸다.\u003c/p>\n\u003cp>원래 조동사가 있는데 \u003ccode>do\u003c/code>를 추가하지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Don&#39;t you can swim?\u003cbr>✅ Can&#39;t you swim?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. 축약하지 않으면 \u003ccode>not\u003c/code>의 위치가 다르다\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Isn&#39;t she\u003c/strong> coming?\u003c/p>\n\u003c/blockquote>\n\u003cp>축약을 풀면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Is she not\u003c/strong> coming?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Didn&#39;t you\u003c/strong> receive it?\u003c/p>\n\u003c/blockquote>\n\u003cp>축약을 풀면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Did you not\u003c/strong> receive it?\u003c/p>\n\u003c/blockquote>\n\u003cp>기본 어순:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>조동사 + 주어 + not + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>축약하지 않은 형태는 더 격식 있거나, \u003ccode>not\u003c/code>을 특별히 강조하는 느낌이 날 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. 가장 중요한 것: 대답\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Don&#39;t you like coffee?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로 커피를 좋아한다면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Yes, I do.\u003c/strong>\u003cbr>좋아해.\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로 좋아하지 않는다면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>No, I don&#39;t.\u003c/strong>\u003cbr>안 좋아해.\u003c/p>\n\u003c/blockquote>\n\u003cp>영어에서는 질문의 부정에 맞장구치는지가 아니라 \u003cstrong>대답하는 사실이 긍정인지 부정인지\u003c/strong>를 기준으로 삼는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. 한국어와 비교하기\u003c/h2>\n\u003cp>한국어:\u003c/p>\n\u003cblockquote>\n\u003cp>“너 커피 안 좋아하지?”\u003cbr>“응, 안 좋아해.”\u003c/p>\n\u003c/blockquote>\n\u003cp>이 “응”을 그대로 \u003ccode>Yes\u003c/code>로 옮기면 혼동할 수 있다.\u003c/p>\n\u003cp>영어:\u003c/p>\n\u003cblockquote>\n\u003cp>“Don&#39;t you like coffee?”\u003cbr>“\u003cstrong>No, I don&#39;t.\u003c/strong>”\u003c/p>\n\u003c/blockquote>\n\u003cp>처음에는 \u003ccode>Yes / No\u003c/code>만 말하지 말고:\u003c/p>\n\u003cblockquote>\n\u003cp>Yes, \u003cstrong>I do\u003c/strong>.\u003cbr>No, \u003cstrong>I don&#39;t\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 동사까지 말하면 뜻이 명확해진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. 과거 질문의 대답\u003c/h2>\n\u003cblockquote>\n\u003cp>Didn&#39;t she come yesterday?\u003cbr>그녀 어제 오지 않았어?\u003c/p>\n\u003c/blockquote>\n\u003cp>왔다면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Yes, she did.\u003c/strong>\u003cbr>왔어.\u003c/p>\n\u003c/blockquote>\n\u003cp>오지 않았다면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>No, she didn&#39;t.\u003c/strong>\u003cbr>안 왔어.\u003c/p>\n\u003c/blockquote>\n\u003cp>현재완료도 마찬가지다.\u003c/p>\n\u003cblockquote>\n\u003cp>Haven&#39;t you finished?\u003cbr>\u003cstrong>Yes, I have.\u003c/strong> / \u003cstrong>No, I haven&#39;t.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>질문의 시제와 조동사를 맞춘다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">9. 제안과 감탄\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Why don&#39;t we take a break?\u003c/strong>\u003cbr>우리 잠깐 쉴까?\u003c/p>\n\u003c/blockquote>\n\u003cp>이 표현은 보통 “왜 안 쉬는지 이유를 설명해라”보다 \u003cstrong>쉬자는 제안\u003c/strong>이다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Isn&#39;t this view beautiful?\u003c/strong>\u003cbr>이 경치 정말 아름답지 않니?\u003c/p>\n\u003c/blockquote>\n\u003cp>이는 화자가 아름답다고 느끼며 상대의 동의를 구하는 말이다.\u003c/p>\n\u003cp>형태만으로 뜻을 하나로 고정하지 않고 상황을 함께 읽는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">10. 말투에 주의\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Didn&#39;t you read my message?\u003c/strong>\u003cbr>내 메시지 안 읽었어?\u003c/p>\n\u003c/blockquote>\n\u003cp>문법적으로는 평범한 확인 질문이지만, 말투에 따라 상대를 나무라는 느낌이 날 수 있다.\u003c/p>\n\u003cp>중립적으로 확인하려면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Did you get my message?\u003c/strong>\u003cbr>내 메시지 받았어?\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 긍정 의문문을 선택할 수도 있다. 부정의문문이 항상 더 공손한 것은 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">핵심\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>부정의문문 = 부정형 조동사/be동사 + 주어 + …?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>대답은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>실제로 그렇다 → Yes + 긍정\u003c/strong>\u003cbr>\u003cstrong>실제로 그렇지 않다 → No + 부정\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">연습\u003c/h2>\n\u003col>\n\u003cli>\u003cp>\u003cstrong>Doesn&#39;t she work / Doesn&#39;t she works\u003c/strong> here?\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Didn&#39;t you \u003cstrong>see / saw\u003c/strong> the sign?\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“Aren&#39;t you tired?”에 실제로 피곤하다고 답한다.\u003c/p>\n\u003cp> → \u003cstrong>Yes, I am. / No, I&#39;m not.\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“Didn&#39;t he call?”에 실제로 전화하지 않았다고 답한다.\u003c/p>\n\u003cp> → \u003cstrong>Yes, he did. / No, he didn&#39;t.\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Isn&#39;t she coming?의 축약을 풀면 → \u003cstrong>Is she not coming? / Is not she coming?\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>쉬자는 제안 → \u003cstrong>Why don&#39;t we take a break? / Why we don&#39;t take a break?\u003c/strong>\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>96단계 — 동의 표현 \u003c/strong>\u003cstrong>\u003ccode>so / neither / too / either\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 보통 의문문과 비교","depth":2},{"id":"reading-2","label":"일반 의문문","depth":3},{"id":"reading-3","label":"부정의문문","depth":3},{"id":"reading-4","label":"2. be동사로 만들기","depth":2},{"id":"reading-5","label":"3. 일반동사로 만들기","depth":2},{"id":"reading-6","label":"4. 조동사도 같은 방식","depth":2},{"id":"reading-7","label":"5. 축약하지 않으면 not의 위치가 다르다","depth":2},{"id":"reading-8","label":"6. 가장 중요한 것: 대답","depth":2},{"id":"reading-9","label":"7. 한국어와 비교하기","depth":2},{"id":"reading-10","label":"8. 과거 질문의 대답","depth":2},{"id":"reading-11","label":"9. 제안과 감탄","depth":2},{"id":"reading-12","label":"10. 말투에 주의","depth":2},{"id":"reading-13","label":"핵심","depth":2},{"id":"reading-14","label":"연습","depth":2}],"origin":"notion","characters":3040,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-1","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-12","topic-11":"reading-13","topic-12":"reading-14"}},{"id":96,"title":"96단계 — 동의 표현 so / neither / too / either","html":"\u003ch1 id=\"lesson-title\" data-id=\"96\">96단계 — 동의 표현 so / neither / too / either\u003c/h1>\n\u003cp>누군가 말한다.\u003c/p>\n\u003cblockquote>\n\u003cp>I like coffee.\u003cbr>나는 커피를 좋아해.\u003c/p>\n\u003c/blockquote>\n\u003cp>나도 그렇다면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>So do I.\u003c/strong>\u003cbr>나도 그래.\u003c/p>\n\u003c/blockquote>\n\u003cp>이번에는 앞의 말을 반복하지 않고 \u003cstrong>같은 상태·행동을 공유한다고 말하는 방법\u003c/strong>을 배운다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 긍정 동의: \u003ccode>So + 조동사 + 주어\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>A: I work from home.\u003cbr>B: \u003cstrong>So do I.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>나도 재택근무해.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>So + 조동사/be동사 + 주어\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>do I\u003c/code>처럼 순서가 바뀌지만 질문이 아니다. “나도 그렇다”라는 \u003cstrong>동의 표현의 도치\u003c/strong>다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 앞 문장에 맞는 동사를 고른다\u003c/h2>\n\u003cp>be동사:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m hungry. → \u003cstrong>So am I.\u003c/strong>\u003cbr>나 배고파. → 나도.\u003c/p>\n\u003c/blockquote>\n\u003cp>조동사:\u003c/p>\n\u003cblockquote>\n\u003cp>I can swim. → \u003cstrong>So can I.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>현재완료:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ve finished. → \u003cstrong>So have I.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>일반동사:\u003c/p>\n\u003cblockquote>\n\u003cp>I like tea. → \u003cstrong>So do I.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>so\u003c/code> 뒤에 무조건 \u003ccode>do\u003c/code>가 오는 것은 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 시제와 새 주어도 맞춘다\u003c/h2>\n\u003cblockquote>\n\u003cp>A: I went there last year.\u003cbr>B: \u003cstrong>So did I.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>과거이므로 \u003ccode>did\u003c/code>다.\u003c/p>\n\u003cp>이번에는 다른 사람의 동의를 말하면:\u003c/p>\n\u003cblockquote>\n\u003cp>I like this book, and \u003cstrong>so does Mina\u003c/strong>.\u003cbr>나는 이 책을 좋아하고, 미나도 그렇다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>Mina\u003c/code>가 새 주어이므로 \u003ccode>does\u003c/code>를 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m tired, and \u003cstrong>so are they\u003c/strong>.\u003cbr>나는 피곤하고 그들도 그렇다.\u003c/p>\n\u003c/blockquote>\n\u003cp>앞 문장의 단어를 복사만 하지 않고 \u003cstrong>뒤의 주어\u003c/strong>와도 맞춘다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>too\u003c/code>를 쓰는 방법\u003c/h2>\n\u003cblockquote>\n\u003cp>I like coffee.\u003cbr>\u003cstrong>I do too.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>또는 문장을 다시 말해도 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I like coffee too.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>be동사라면:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m tired.\u003cbr>\u003cstrong>I am too.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>어순 비교:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>So do I.\u003c/strong>\u003cbr>\u003cstrong>I do too.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>too\u003c/code> 방식에서는 주어와 조동사를 뒤집지 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. 부정 동의: \u003ccode>Neither + 조동사 + 주어\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>A: I don&#39;t eat meat.\u003cbr>B: \u003cstrong>Neither do I.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나도 고기를 먹지 않아.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>neither\u003c/code> 자체에 부정의 뜻이 있다.\u003c/p>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ Neither \u003cstrong>do\u003c/strong> I.\u003cbr>❌ Neither \u003cstrong>don&#39;t\u003c/strong> I.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Neither + 긍정형 조동사/be동사 + 주어\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">6. 부정 동의의 여러 형태\u003c/h2>\n\u003cblockquote>\n\u003cp>I&#39;m not ready. → \u003cstrong>Neither am I.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I can&#39;t drive. → \u003cstrong>Neither can I.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I haven&#39;t seen it. → \u003cstrong>Neither have I.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I didn&#39;t go. → \u003cstrong>Neither did I.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>앞 문장과 같은 조동사·시제를 쓰되, \u003cstrong>neither가 부정을 담당\u003c/strong>한다.\u003c/p>\n\u003cp>\u003ccode>Nor do I.\u003c/code>처럼 \u003ccode>nor\u003c/code>를 쓰는 형태도 가능하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">7. \u003ccode>either\u003c/code>를 쓰는 방법\u003c/h2>\n\u003cblockquote>\n\u003cp>I don&#39;t like it.\u003cbr>\u003cstrong>I don&#39;t either.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;m not tired.\u003cbr>\u003cstrong>I&#39;m not either.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이때는 문장 자체가 부정형이다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>부정문 + either\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>비교:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Neither do I.\u003c/strong>\u003cbr>\u003cstrong>I don&#39;t either.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 “나도 안 그래”다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I don&#39;t too.\u003cbr>✅ I don&#39;t either.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">8. 동의하지 않을 때\u003c/h2>\n\u003cblockquote>\n\u003cp>A: I like spicy food.\u003cbr>B: \u003cstrong>I don&#39;t.\u003c/strong>\u003cbr>나는 안 좋아해.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>A: I haven&#39;t finished.\u003cbr>B: \u003cstrong>I have.\u003c/strong>\u003cbr>나는 끝냈어.\u003c/p>\n\u003c/blockquote>\n\u003cp>상대와 다르면 \u003ccode>so / neither\u003c/code>를 쓰지 않는다. \u003cstrong>내 쪽의 긍정·부정\u003c/strong>을 그대로 말한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">9. \u003ccode>So do I\u003c/code>와 \u003ccode>So I do\u003c/code>는 다르다\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>So do I.\u003c/strong>\u003cbr>나도 그래.\u003c/p>\n\u003c/blockquote>\n\u003cp>주어가 바뀌어 같은 사실을 말한다.\u003c/p>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>A: You have my pen.\u003cbr>B: \u003cstrong>So I do!\u003c/strong>\u003cbr>아, 정말 내가 가지고 있네!\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>So I do\u003c/code>는 남의 말을 듣고 \u003cstrong>그 사실을 인정하거나 깨닫는 표현\u003c/strong>이다.\u003c/p>\n\u003cp>“나도”를 말하려고 어순을 바꾸면 뜻이 달라진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">10. 짧은 회화 표현\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Me too.\u003c/strong>\u003cbr>나도.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Me neither.\u003c/strong>\u003cbr>나도 안 그래.\u003c/p>\n\u003c/blockquote>\n\u003cp>일상 대화에서 널리 쓰는 표현이다. 문장을 분석할 때는 \u003ccode>So do I / Neither do I\u003c/code>의 완전한 구조도 함께 익혀 두면 조동사와 시제를 이해하기 좋다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">핵심 비교\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\u003cthead>\u003ctr>\u003cth scope=\"col\">앞의 말\u003c/th>\u003cth scope=\"col\">도치 방식\u003c/th>\u003cth scope=\"col\">보통 어순\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>I like it.\u003c/td>\u003ctd>So do I.\u003c/td>\u003ctd>I do too.\u003c/td>\u003c/tr>\u003ctr>\u003ctd>I&#39;m tired.\u003c/td>\u003ctd>So am I.\u003c/td>\u003ctd>I am too.\u003c/td>\u003c/tr>\u003ctr>\u003ctd>I don&#39;t like it.\u003c/td>\u003ctd>Neither do I.\u003c/td>\u003ctd>I don&#39;t either.\u003c/td>\u003c/tr>\u003ctr>\u003ctd>I can&#39;t swim.\u003c/td>\u003ctd>Neither can I.\u003c/td>\u003ctd>I can&#39;t either.\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">연습\u003c/h2>\n\u003col>\n\u003cli>\u003cp>“I&#39;m tired.” → \u003cstrong>So am I. / So do I.\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“I went there.” → \u003cstrong>So did I. / So do I.\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“I haven&#39;t finished.” → \u003cstrong>Neither have I. / Neither haven&#39;t I.\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“I don&#39;t like it.” → I don&#39;t \u003cstrong>too / either\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I like tea, and so \u003cstrong>does / do\u003c/strong> Mina.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“나도 그래.”라는 뜻 → \u003cstrong>So do I. / So I do.\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“I can swim.”에 자신은 못한다고 답한다. → \u003cstrong>I can&#39;t. / Neither can I.\u003c/strong>\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>97단계 — 구동사와 목적어 위치\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 긍정 동의: So + 조동사 + 주어","depth":2},{"id":"reading-2","label":"2. 앞 문장에 맞는 동사를 고른다","depth":2},{"id":"reading-3","label":"3. 시제와 새 주어도 맞춘다","depth":2},{"id":"reading-4","label":"4. too를 쓰는 방법","depth":2},{"id":"reading-5","label":"5. 부정 동의: Neither + 조동사 + 주어","depth":2},{"id":"reading-6","label":"6. 부정 동의의 여러 형태","depth":2},{"id":"reading-7","label":"7. either를 쓰는 방법","depth":2},{"id":"reading-8","label":"8. 동의하지 않을 때","depth":2},{"id":"reading-9","label":"9. So do I와 So I do는 다르다","depth":2},{"id":"reading-10","label":"10. 짧은 회화 표현","depth":2},{"id":"reading-11","label":"핵심 비교","depth":2},{"id":"reading-12","label":"연습","depth":2}],"origin":"notion","characters":3151,"aliases":{"structure":"reading-6","examples":"concept","contrast":"reading-11","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-7","topic-8":"reading-8","topic-9":"reading-9","topic-10":"reading-10","topic-11":"reading-11","topic-12":"reading-12"}},{"id":97,"title":"97단계 — 구동사와 목적어 위치","html":"\u003ch1 id=\"lesson-title\" data-id=\"97\">97단계 — 구동사와 목적어 위치\u003c/h1>\n\u003cp>이번에는 두세 단어가 모여 하나의 동사처럼 쓰이는 표현을 배운다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>turn on\u003c/strong> = 켜다\u003cbr>\u003cstrong>give up\u003c/strong> = 포기하다\u003cbr>\u003cstrong>look for\u003c/strong> = 찾다\u003c/p>\n\u003c/blockquote>\n\u003cp>단어를 따로 해석한 뜻과 전체 뜻이 다를 수 있다.\u003c/p>\n\u003cp>그리고 중요한 문제가 하나 더 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>목적어를 어느 위치에 놓아야 하는가?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 동사와 짧은 말이 한 묶음\u003c/h2>\n\u003cblockquote>\n\u003cp>Please \u003cstrong>turn off\u003c/strong> the light.\u003cbr>불을 꺼 주세요.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>turn\u003c/code>만 보면 “돌리다”지만, \u003ccode>turn off\u003c/code>는 여기서 \u003cstrong>끄다\u003c/strong>다.\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>gave up\u003c/strong> smoking.\u003cbr>그녀는 담배를 끊었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>동사와 부사적 소사(particle)가 묶인 표현을 좁은 의미의 구동사라고 한다. 학습에서는 \u003ccode>look for\u003c/code> 같은 \u003cstrong>전치사 동사\u003c/strong>까지 함께 다루기도 한다. 이름보다 \u003cstrong>뜻과 어순\u003c/strong>을 함께 익히는 것이 중요하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 목적어가 없는 구동사\u003c/h2>\n\u003cblockquote>\n\u003cp>I \u003cstrong>woke up\u003c/strong> early.\u003cbr>나는 일찍 잠에서 깼다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>The car \u003cstrong>broke down\u003c/strong>.\u003cbr>차가 고장 났다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 용법에서는 뒤에 목적어를 붙이지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>주어 + 구동사\u003c/p>\n\u003c/blockquote>\n\u003cp>만으로 핵심 문장이 완성된다. 모든 구동사가 “동사 + 목적어 + 짧은 말”로 나뉘는 것은 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 분리 가능한 구동사\u003c/h2>\n\u003cp>\u003ccode>turn on\u003c/code>은 이 의미에서 분리할 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>Turn \u003cstrong>on the light\u003c/strong>.\u003cbr>Turn \u003cstrong>the light on\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다:\u003c/p>\n\u003cblockquote>\n\u003cp>불을 켜라.\u003c/p>\n\u003c/blockquote>\n\u003cp>목적어가 일반 명사라면 두 위치가 가능하다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>동사 + 소사 + 명사 목적어\u003c/strong>\u003cbr>\u003cstrong>동사 + 명사 목적어 + 소사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. 목적어가 대명사면 중간에\u003c/h2>\n\u003cp>같은 불을 \u003ccode>it\u003c/code>으로 받으면:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ Turn \u003cstrong>it on\u003c/strong>.\u003cbr>❌ Turn \u003cstrong>on it\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>turn on\u003c/code>의 “켜다”라는 분리 가능한 용법에서, 대명사 목적어는 \u003cstrong>동사와 소사 사이\u003c/strong>에 둔다.\u003c/p>\n\u003cblockquote>\n\u003cp>Pick \u003cstrong>them up\u003c/strong>.\u003cbr>그것들을 주워라 / 그들을 데리러 가라.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Write \u003cstrong>it down\u003c/strong>.\u003cbr>그것을 적어라.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ Write down it.\u003cbr>✅ Write it down.\u003c/p>\n\u003c/blockquote>\n\u003cp>이것이 이번 단계의 가장 중요한 규칙이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. 명사 목적어가 길면\u003c/h2>\n\u003cblockquote>\n\u003cp>Turn off \u003cstrong>all the lights in the meeting room\u003c/strong>.\u003cbr>회의실의 모든 불을 꺼라.\u003c/p>\n\u003c/blockquote>\n\u003cp>목적어가 길 때는 동사와 소사를 붙여 두고 뒤에 긴 목적어를 놓는 편이 읽기 쉽다.\u003c/p>\n\u003cblockquote>\n\u003cp>turn all the lights in the meeting room off\u003c/p>\n\u003c/blockquote>\n\u003cp>도 문법적으로 가능하지만 두 부분이 멀리 떨어진다.\u003c/p>\n\u003cp>\u003cstrong>문법적으로 가능함\u003c/strong>과 \u003cstrong>읽기 쉬운 배열\u003c/strong>을 구분한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">6. 분리할 수 없는 표현\u003c/h2>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>looking for my keys\u003c/strong>.\u003cbr>나는 열쇠를 찾고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>look for\u003c/code>의 이 용법에서는 \u003ccode>for\u003c/code> 뒤에 목적어가 온다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I&#39;m looking my keys for.\u003cbr>✅ I&#39;m looking for my keys.\u003c/p>\n\u003c/blockquote>\n\u003cp>대명사도 마찬가지다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ I&#39;m looking \u003cstrong>for them\u003c/strong>.\u003cbr>❌ I&#39;m looking \u003cstrong>them for\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>앞의 \u003ccode>turn it on\u003c/code> 규칙을 모든 동사 조합에 적용하면 안 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">7. 두 종류를 나란히 비교\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\u003cthead>\u003ctr>\u003cth scope=\"col\">표현\u003c/th>\u003cth scope=\"col\">명사 목적어\u003c/th>\u003cth scope=\"col\">대명사 목적어\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>turn on 켜다\u003c/td>\u003ctd>turn on the light / turn the light on\u003c/td>\u003ctd>turn it on\u003c/td>\u003c/tr>\u003ctr>\u003ctd>pick up 집어 들다\u003c/td>\u003ctd>pick up the bag / pick the bag up\u003c/td>\u003ctd>pick it up\u003c/td>\u003c/tr>\u003ctr>\u003ctd>look for 찾다\u003c/td>\u003ctd>look for the key\u003c/td>\u003ctd>look for it\u003c/td>\u003c/tr>\u003ctr>\u003ctd>look after 돌보다\u003c/td>\u003ctd>look after the child\u003c/td>\u003ctd>look after her\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\n\u003cblockquote>\n\u003cp>\u003cstrong>분리 가능 여부는 표현별로 익힌다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>사전의 예문이나 \u003ccode>separable / inseparable\u003c/code> 표시를 함께 확인하면 좋다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">8. 세 단어로 이루어진 표현\u003c/h2>\n\u003cblockquote>\n\u003cp>I \u003cstrong>look forward to\u003c/strong> the trip.\u003cbr>나는 그 여행이 기대된다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We \u003cstrong>ran out of\u003c/strong> milk.\u003cbr>우유가 떨어졌다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이런 표현은 마지막 전치사 뒤에 목적어를 놓는다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ We ran out \u003cstrong>of it\u003c/strong>.\u003cbr>❌ We ran it out of.\u003c/p>\n\u003c/blockquote>\n\u003cp>특히 \u003ccode>look forward to\u003c/code>의 \u003ccode>to\u003c/code>는 전치사다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m looking forward to \u003cstrong>seeing you\u003c/strong>.\u003cbr>너를 만나는 것이 기대된다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ looking forward to see you\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">9. 같은 표현도 뜻에 따라 달라질 수 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>She \u003cstrong>took off\u003c/strong> her coat.\u003cbr>그녀는 코트를 벗었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 목적어가 있음, 분리 가능\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>took her coat off\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>The plane \u003cstrong>took off\u003c/strong>.\u003cbr>비행기가 이륙했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 이 의미에서는 목적어가 없음\u003c/p>\n\u003cp>철자가 같은 표현이라도 \u003cstrong>뜻과 문장 구조를 한 쌍으로\u003c/strong> 기억한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">핵심\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>turn on the light = turn the light on\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 대명사는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>turn it on\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>분리 불가능한 표현은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>look for it / look after her\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>모든 구동사를 같은 방식으로 나누지 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">연습\u003c/h2>\n\u003col>\n\u003cli>\u003cp>불을 꺼 줘. → \u003cstrong>Turn it off. / Turn off it.\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I&#39;m \u003cstrong>looking for my keys / looking my keys for\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Write \u003cstrong>it down / down it\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Please look \u003cstrong>after her / her after\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I look forward to \u003cstrong>seeing / see\u003c/strong> you.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“코트를 벗었다.” → She \u003cstrong>took her coat off / took off it\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>We ran out \u003cstrong>of milk / milk of\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>98단계 — 상관접속사\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 동사와 짧은 말이 한 묶음","depth":2},{"id":"reading-2","label":"2. 목적어가 없는 구동사","depth":2},{"id":"reading-3","label":"3. 분리 가능한 구동사","depth":2},{"id":"reading-4","label":"4. 목적어가 대명사면 중간에","depth":2},{"id":"reading-5","label":"5. 명사 목적어가 길면","depth":2},{"id":"reading-6","label":"6. 분리할 수 없는 표현","depth":2},{"id":"reading-7","label":"7. 두 종류를 나란히 비교","depth":2},{"id":"reading-8","label":"8. 세 단어로 이루어진 표현","depth":2},{"id":"reading-9","label":"9. 같은 표현도 뜻에 따라 달라질 수 있다","depth":2},{"id":"reading-10","label":"핵심","depth":2},{"id":"reading-11","label":"연습","depth":2}],"origin":"notion","characters":3263,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-7","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-7","topic-8":"reading-8","topic-9":"reading-9","topic-10":"reading-10","topic-11":"reading-11","topic-12":"concept"}},{"id":98,"title":"98단계 — 상관접속사 both...and / either...or / neither...nor / not only...but also","html":"\u003ch1 id=\"lesson-title\" data-id=\"98\">98단계 — 상관접속사 both...and / either...or / neither...nor / not only...but also\u003c/h1>\n\u003cp>이번에는 두 표현을 \u003cstrong>짝을 이루어 연결하는 방법\u003c/strong>을 배운다.\u003c/p>\n\u003cblockquote>\n\u003cp>both A and B = A와 B 둘 다\u003cbr>either A or B = A 또는 B 중 하나\u003cbr>neither A nor B = A도 B도 아님\u003cbr>not only A but also B = A뿐만 아니라 B도\u003c/p>\n\u003c/blockquote>\n\u003cp>의미만 외우지 말고 \u003cstrong>A와 B 자리에 어떤 구조가 오는지\u003c/strong>를 함께 본다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>both A and B\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>both tea and coffee\u003c/strong>.\u003cbr>나는 차와 커피를 둘 다 좋아한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>tea\u003c/code>와 \u003ccode>coffee\u003c/code>라는 두 명사를 연결한다.\u003c/p>\n\u003cp>형용사도 가능하다.\u003c/p>\n\u003cblockquote>\n\u003cp>The room is \u003cstrong>both quiet and comfortable\u003c/strong>.\u003cbr>그 방은 조용하고 편안하기도 하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이번에는 \u003ccode>quiet\u003c/code>과 \u003ccode>comfortable\u003c/code>이 연결된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 주어를 연결하면 복수\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Both Mina and Jun are\u003c/strong> here.\u003cbr>미나와 준이 둘 다 여기 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>두 사람이 주어이므로:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ Both Mina and Jun \u003cstrong>are\u003c/strong> ready.\u003cbr>❌ Both Mina and Jun \u003cstrong>is\u003c/strong> ready.\u003c/p>\n\u003c/blockquote>\n\u003cp>이는 90단계의 \u003ccode>both\u003c/code>와 같은 “둘 다”의 감각이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>either A or B\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>You can have \u003cstrong>either tea or coffee\u003c/strong>.\u003cbr>차와 커피 중 하나를 마실 수 있어.\u003c/p>\n\u003c/blockquote>\n\u003cp>두 선택지를 제시한다.\u003c/p>\n\u003cp>행동을 연결할 수도 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>We can \u003cstrong>either walk or take a bus\u003c/strong>.\u003cbr>우리는 걷거나 버스를 탈 수 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조를 보면:\u003c/p>\n\u003cblockquote>\n\u003cp>walk / take a bus\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 \u003ccode>can\u003c/code> 뒤에 오는 동사원형 덩어리다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>neither A nor B\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>neither tea nor coffee\u003c/strong>.\u003cbr>나는 차도 커피도 좋아하지 않는다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이미 부정의 뜻이 있으므로 같은 의미로 \u003ccode>don&#39;t\u003c/code>를 추가하지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I don&#39;t like neither tea nor coffee.\u003cbr>✅ I like neither tea nor coffee.\u003c/p>\n\u003c/blockquote>\n\u003cp>일상적으로는:\u003c/p>\n\u003cblockquote>\n\u003cp>I don&#39;t like \u003cstrong>either tea or coffee\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>라고도 할 수 있다. \u003cstrong>neither … nor\u003c/strong>와 \u003cstrong>not … either … or\u003c/strong>는 같은 부정을 다른 방식으로 표현한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. \u003ccode>either / neither\u003c/code>로 주어를 연결할 때\u003c/h2>\n\u003cp>두 주어가 모두 단수면:\u003c/p>\n\u003cblockquote>\n\u003cp>Either Mina or Jun \u003cstrong>is\u003c/strong> coming.\u003cbr>미나나 준 중 한 명이 온다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Neither Mina nor Jun \u003cstrong>knows\u003c/strong> the answer.\u003cbr>미나도 준도 답을 모른다.\u003c/p>\n\u003c/blockquote>\n\u003cp>단수와 복수가 섞이면, 일반적으로 \u003cstrong>동사에 가까운 주어\u003c/strong>에 맞추는 방식이 많이 쓰인다.\u003c/p>\n\u003cblockquote>\n\u003cp>Either the teacher or the students \u003cstrong>are\u003c/strong> responsible.\u003c/p>\n\u003c/blockquote>\n\u003cp>다만 이런 문장은 어색하게 느껴질 수 있어 명확하게 다시 쓰는 편이 좋을 때도 있다. \u003ccode>either / neither\u003c/code>라는 단어만 보고 무조건 단수동사로 고정하지 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">6. \u003ccode>not only A but also B\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>She speaks \u003cstrong>not only English but also Spanish\u003c/strong>.\u003cbr>그녀는 영어뿐만 아니라 스페인어도 한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>처음 정보에 두 번째 정보를 더하며 강조한다.\u003c/p>\n\u003cblockquote>\n\u003cp>The task is \u003cstrong>not only difficult but also time-consuming\u003c/strong>.\u003cbr>그 일은 어려울 뿐만 아니라 시간도 많이 든다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 형용사끼리 연결한다.\u003c/p>\n\u003cp>\u003ccode>also\u003c/code>는 문맥에 따라 생략되기도 하지만, 처음에는 전체 짝을 익힌다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">7. 짝의 양쪽 구조를 맞추기\u003c/h2>\n\u003cblockquote>\n\u003cp>She enjoys \u003cstrong>both reading and swimming\u003c/strong>.\u003cbr>그녀는 독서와 수영을 모두 즐긴다.\u003c/p>\n\u003c/blockquote>\n\u003cp>두 동명사가 연결된다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ both \u003cstrong>reading\u003c/strong> and \u003cstrong>to swim\u003c/strong>\u003cbr>✅ both \u003cstrong>reading\u003c/strong> and \u003cstrong>swimming\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>He is \u003cstrong>not only a teacher but also a writer\u003c/strong>.\u003cbr>그는 교사일 뿐만 아니라 작가이기도 하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>두 명사구가 같은 역할을 한다. 이것을 \u003cstrong>병렬구조\u003c/strong>라고 하며 119단계에서 더 자세히 다룬다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">8. 위치가 의미를 보여준다\u003c/h2>\n\u003cblockquote>\n\u003cp>She \u003cstrong>not only writes articles but also edits books\u003c/strong>.\u003cbr>그녀는 기사를 쓸 뿐 아니라 책도 편집한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 두 행동을 연결\u003c/p>\n\u003cblockquote>\n\u003cp>She writes \u003cstrong>not only articles but also books\u003c/strong>.\u003cbr>그녀는 기사뿐 아니라 책도 쓴다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003ccode>writes\u003c/code>의 두 목적어를 연결\u003c/p>\n\u003cp>\u003ccode>not only\u003c/code>를 어디에 두느냐에 따라 \u003cstrong>무엇과 무엇을 비교하는지\u003c/strong>가 달라진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">9. 문두의 \u003ccode>Not only\u003c/code>는 별도 주의\u003c/h2>\n\u003cp>보통 문장:\u003c/p>\n\u003cblockquote>\n\u003cp>She not only writes well but also speaks well.\u003c/p>\n\u003c/blockquote>\n\u003cp>앞으로 옮겨 강조하면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Not only does she write\u003c/strong> well, but she also speaks well.\u003c/p>\n\u003c/blockquote>\n\u003cp>첫 절에서 \u003ccode>does + 주어 + 동사원형\u003c/code>으로 도치된다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Not only she writes well …\u003cbr>✅ Not only does she write well …\u003c/p>\n\u003c/blockquote>\n\u003cp>다만 \u003ccode>Not only Mina but also Jun came.\u003c/code>처럼 \u003cstrong>주어 자체를 연결할 때는\u003c/strong> 이 도치를 하지 않는다. 문두에 같은 단어가 있다고 항상 같은 구조는 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">10. 부정의 범위를 조심하기\u003c/h2>\n\u003cblockquote>\n\u003cp>I don&#39;t like \u003cstrong>both\u003c/strong> options.\u003c/p>\n\u003c/blockquote>\n\u003cp>“둘 다 좋아하지 않는다”인지 “둘을 모두 좋아하는 건 아니다”인지 모호하게 들릴 수 있다.\u003c/p>\n\u003cp>어느 것도 좋아하지 않음을 분명히 하려면:\u003c/p>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>neither option\u003c/strong>.\u003cbr>두 선택지 중 어느 것도 마음에 들지 않는다.\u003c/p>\n\u003c/blockquote>\n\u003cp>한쪽만 마음에 든다면 그 선택지를 직접 밝히는 것이 가장 명확하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">핵심\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>both … and …\u003c/strong>\u003cbr>\u003cstrong>either … or …\u003c/strong>\u003cbr>\u003cstrong>neither … nor …\u003c/strong>\u003cbr>\u003cstrong>not only … but also …\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>확인할 것:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>의미 → 연결하는 두 요소 → 같은 역할·형태 → 동사의 수 일치\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">연습\u003c/h2>\n\u003col>\n\u003cli>\u003cp>Both Mina and Jun \u003cstrong>is / are\u003c/strong> ready.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>You can either stay \u003cstrong>or / nor\u003c/strong> leave.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She likes neither tea \u003cstrong>or / nor\u003c/strong> coffee.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>He enjoys both \u003cstrong>reading and cooking / reading and to cook\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Not only \u003cstrong>does she write / she writes\u003c/strong> well, but she also speaks well.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“그는 교사이자 작가다.” → He is both \u003cstrong>a teacher and a writer / a teacher or a writer\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Neither Mina nor Jun \u003cstrong>knows / know\u003c/strong> the answer. → 격식 있는 기본 작문\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>99단계 — \u003c/strong>\u003cstrong>\u003ccode>-ing / -ed\u003c/code>\u003c/strong>\u003cstrong> 분사형용사\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. both A and B","depth":2},{"id":"reading-2","label":"2. 주어를 연결하면 복수","depth":2},{"id":"reading-3","label":"3. either A or B","depth":2},{"id":"reading-4","label":"4. neither A nor B","depth":2},{"id":"reading-5","label":"5. either / neither로 주어를 연결할 때","depth":2},{"id":"reading-6","label":"6. not only A but also B","depth":2},{"id":"reading-7","label":"7. 짝의 양쪽 구조를 맞추기","depth":2},{"id":"reading-8","label":"8. 위치가 의미를 보여준다","depth":2},{"id":"reading-9","label":"9. 문두의 Not only는 별도 주의","depth":2},{"id":"reading-10","label":"10. 부정의 범위를 조심하기","depth":2},{"id":"reading-11","label":"핵심","depth":2},{"id":"reading-12","label":"연습","depth":2}],"origin":"notion","characters":3741,"aliases":{"structure":"reading-7","examples":"concept","contrast":"concept","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-7","topic-8":"reading-8","topic-9":"reading-9","topic-10":"reading-10","topic-11":"reading-11","topic-12":"reading-12"}},{"id":99,"title":"99단계 — -ing / -ed 분사형용사","html":"\u003ch1 id=\"lesson-title\" data-id=\"99\">99단계 — -ing / -ed 분사형용사\u003c/h1>\n\u003cp>이번에는 자주 헷갈리는 두 문장을 비교한다.\u003c/p>\n\u003cblockquote>\n\u003cp>I am \u003cstrong>bored\u003c/strong>.\u003cbr>나는 지루하다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I am \u003cstrong>boring\u003c/strong>.\u003cbr>나는 남을 지루하게 하는 사람이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>끝부분 하나가 바뀌지만 뜻은 크게 달라진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 감정을 느끼는 쪽과 일으키는 쪽\u003c/h2>\n\u003cp>재미없는 영화를 보고 있다.\u003c/p>\n\u003cp>영화가 지루함을 일으킨다.\u003c/p>\n\u003cblockquote>\n\u003cp>The film is \u003cstrong>boring\u003c/strong>.\u003cbr>그 영화는 지루하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>나는 지루함을 느낀다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>bored\u003c/strong>.\u003cbr>나는 지루하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>기본 감각:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>-ing → 그런 감정을 일으키는 성질\u003c/strong>\u003cbr>\u003cstrong>-ed → 그런 감정을 느끼는 상태\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>interesting / interested\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>This book is \u003cstrong>interesting\u003c/strong>.\u003cbr>이 책은 흥미롭다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>interested in\u003c/strong> this book.\u003cbr>나는 이 책에 관심이 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>책이 관심을 일으키고, 내가 관심을 느낀다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ I&#39;m \u003cstrong>interested in\u003c/strong> history.\u003cbr>❌ I&#39;m \u003cstrong>interesting in\u003c/strong> history.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>interested\u003c/code>는 자주 \u003ccode>in\u003c/code>과 함께 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>exciting / excited\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>The trip sounds \u003cstrong>exciting\u003c/strong>.\u003cbr>그 여행은 신날 것 같다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We&#39;re \u003cstrong>excited about\u003c/strong> the trip.\u003cbr>우리는 그 여행 때문에 들떠 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>한국어로 둘 다 “신나다”라고 옮길 수 있어도, 영어에서는 \u003cstrong>무엇이 감정을 일으키고 누가 느끼는지\u003c/strong> 구분한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. 사람에게도 \u003ccode>-ing\u003c/code>를 쓴다\u003c/h2>\n\u003cblockquote>\n\u003cp>She&#39;s an \u003cstrong>interesting person\u003c/strong>.\u003cbr>그녀는 흥미로운 사람이다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He&#39;s a \u003cstrong>boring speaker\u003c/strong>.\u003cbr>그는 청중을 지루하게 만드는 연설자다.\u003c/p>\n\u003c/blockquote>\n\u003cp>사람도 다른 사람에게 감정을 일으킬 수 있다.\u003c/p>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>사람 → 무조건 -ed ❌\u003cbr>사물 → 무조건 -ing ❌\u003c/p>\n\u003c/blockquote>\n\u003cp>이런 식으로 외우면 안 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. 자주 쓰는 짝\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\u003cthead>\u003ctr>\u003cth scope=\"col\">감정을 일으킴\u003c/th>\u003cth scope=\"col\">감정을 느낌\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003ctd>surprising 놀라운\u003c/td>\u003ctd>surprised 놀란\u003c/td>\u003c/tr>\u003ctr>\u003ctd>confusing 혼란스러운\u003c/td>\u003ctd>confused 혼란을 느끼는\u003c/td>\u003c/tr>\u003ctr>\u003ctd>disappointing 실망스러운\u003c/td>\u003ctd>disappointed 실망한\u003c/td>\u003c/tr>\u003ctr>\u003ctd>frightening 무서운\u003c/td>\u003ctd>frightened 겁먹은\u003c/td>\u003c/tr>\u003ctr>\u003ctd>tiring 피곤하게 하는\u003c/td>\u003ctd>tired 피곤한\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\n\u003cblockquote>\n\u003cp>The instructions are \u003cstrong>confusing\u003c/strong>.\u003cbr>설명이 헷갈리게 되어 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>confused\u003c/strong>.\u003cbr>나는 헷갈린다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">6. be동사 뒤뿐 아니라 명사 앞에도\u003c/h2>\n\u003cblockquote>\n\u003cp>It was a \u003cstrong>surprising result\u003c/strong>.\u003cbr>놀라운 결과였다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>The \u003cstrong>surprised students\u003c/strong> asked many questions.\u003cbr>놀란 학생들이 많은 질문을 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>명사 앞에서도 같은 의미 관계다.\u003c/p>\n\u003cblockquote>\n\u003cp>an \u003cstrong>exciting game\u003c/strong> = 흥미진진한 경기\u003cbr>\u003cstrong>excited fans\u003c/strong> = 흥분한 팬들\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">7. \u003ccode>-ed\u003c/code>가 과거시제를 뜻하는 것은 아니다\u003c/h2>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>tired now\u003c/strong>.\u003cbr>나는 지금 피곤하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>현재 상태인데도 \u003ccode>tired\u003c/code>다.\u003c/p>\n\u003cblockquote>\n\u003cp>I was \u003cstrong>excited yesterday\u003c/strong>.\u003cbr>나는 어제 들떠 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>시제는 \u003ccode>am / was\u003c/code>가 나타낸다. \u003ccode>excited\u003c/code>는 상태를 설명한다.\u003c/p>\n\u003cp>마찬가지로 \u003ccode>boring\u003c/code>에 \u003ccode>-ing\u003c/code>가 있어도 언제나 현재진행형이라는 뜻은 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>The lesson \u003cstrong>was boring\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>은 과거의 수업이 지루했다는 뜻이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">8. 진행형·수동태와 모양이 겹친다\u003c/h2>\n\u003cblockquote>\n\u003cp>The news \u003cstrong>surprised\u003c/strong> me.\u003cbr>그 소식이 나를 놀라게 했다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I \u003cstrong>was surprised by\u003c/strong> the news.\u003cbr>나는 그 소식에 놀랐다.\u003c/p>\n\u003c/blockquote>\n\u003cp>두 번째는 수동태로 분석할 수 있고, 놀란 상태에 초점을 두면 형용사적 의미도 두드러진다.\u003c/p>\n\u003cblockquote>\n\u003cp>The news \u003cstrong>was surprising\u003c/strong>.\u003cbr>그 소식은 놀라웠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>어미만 보고 판단하기보다 \u003cstrong>주어와 동사의 관계, 뒤의 말, 문맥\u003c/strong>을 함께 본다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">9. 감정이 아닌 분사형용사도 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>a \u003cstrong>broken window\u003c/strong>\u003cbr>깨진 창문\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>boiling water\u003c/strong>\u003cbr>끓고 있는 물\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>a \u003cstrong>written agreement\u003c/strong>\u003cbr>서면 합의서\u003c/p>\n\u003c/blockquote>\n\u003cp>여기에는 “감정을 느끼는 사람”이라는 규칙을 적용할 수 없다.\u003c/p>\n\u003cp>일반적으로 현재분사는 \u003cstrong>능동적·진행 중인 성질\u003c/strong>, 과거분사는 \u003cstrong>수동적·완료된 상태\u003c/strong>와 관련되는 경우가 많다. \u003ccode>fallen leaves\u003c/code>처럼 자동사에서 온 과거분사도 있으므로 과거분사를 전부 수동이라고 외우지는 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">10. 전치사도 함께 익히기\u003c/h2>\n\u003cblockquote>\n\u003cp>interested \u003cstrong>in\u003c/strong> science\u003cbr>과학에 관심 있는\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>excited \u003cstrong>about\u003c/strong> the news\u003cbr>그 소식에 들뜬\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>satisfied \u003cstrong>with\u003c/strong> the result\u003cbr>결과에 만족한\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>worried \u003cstrong>about\u003c/strong> the exam\u003cbr>시험을 걱정하는\u003c/p>\n\u003c/blockquote>\n\u003cp>어떤 형용사냐에 따라 자연스러운 전치사도 달라진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">핵심\u003c/h2>\n\u003cp>감정 표현에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>The film is boring. → 영화가 지루함을 일으킨다.\u003c/strong>\u003cbr>\u003cstrong>I&#39;m bored. → 내가 지루함을 느낀다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>사람·사물 구분이 아니라 \u003cstrong>감정의 원인과 경험자\u003c/strong>를 구분한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">연습\u003c/h2>\n\u003col>\n\u003cli>\u003cp>이 영화가 나를 지루하게 한다. → The film is \u003cstrong>boring / bored\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>나는 과학에 관심이 있다. → I&#39;m \u003cstrong>interested / interesting\u003c/strong> in science.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>흥미로운 사람 → an \u003cstrong>interesting / interested\u003c/strong> person\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>설명 때문에 내가 헷갈린다. → I&#39;m \u003cstrong>confused / confusing\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>깨진 창문 → a \u003cstrong>broken / breaking\u003c/strong> window\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>We&#39;re excited \u003cstrong>about / in\u003c/strong> the trip.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>“나는 지금 피곤하다.” → I \u003cstrong>am tired / was tired\u003c/strong> now.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>100단계 — \u003c/strong>\u003cstrong>\u003ccode>whom / 전치사 + 관계대명사\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 감정을 느끼는 쪽과 일으키는 쪽","depth":2},{"id":"reading-2","label":"2. interesting / interested","depth":2},{"id":"reading-3","label":"3. exciting / excited","depth":2},{"id":"reading-4","label":"4. 사람에게도 -ing를 쓴다","depth":2},{"id":"reading-5","label":"5. 자주 쓰는 짝","depth":2},{"id":"reading-6","label":"6. be동사 뒤뿐 아니라 명사 앞에도","depth":2},{"id":"reading-7","label":"7. -ed가 과거시제를 뜻하는 것은 아니다","depth":2},{"id":"reading-8","label":"8. 진행형·수동태와 모양이 겹친다","depth":2},{"id":"reading-9","label":"9. 감정이 아닌 분사형용사도 있다","depth":2},{"id":"reading-10","label":"10. 전치사도 함께 익히기","depth":2},{"id":"reading-11","label":"핵심","depth":2},{"id":"reading-12","label":"연습","depth":2}],"origin":"notion","characters":3355,"aliases":{"structure":"reading-8","examples":"concept","contrast":"concept","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-7","topic-8":"reading-8","topic-9":"reading-9","topic-10":"reading-10","topic-11":"reading-11","topic-12":"reading-12"}},{"id":100,"title":"100단계 — 관계대명사 심화: whom / 전치사 + 관계대명사","html":"\u003ch1 id=\"lesson-title\" data-id=\"100\">100단계 — 관계대명사 심화: whom / 전치사 + 관계대명사\u003c/h1>\n\u003cp>앞에서 관계대명사는 명사를 뒤에서 설명한다고 배웠다.\u003c/p>\n\u003cblockquote>\n\u003cp>The woman \u003cstrong>who lives next door\u003c/strong> is a doctor.\u003cbr>옆집에 사는 여자는 의사다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이번에는 관계절 안에서 \u003cstrong>목적어 역할을 하는 사람\u003c/strong>, 그리고 \u003cstrong>전치사와 함께 쓰는 관계대명사\u003c/strong>를 자세히 본다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>who\u003c/code>와 \u003ccode>whom\u003c/code>의 기본 역할\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">관계절의 주어\u003c/h3>\n\u003cblockquote>\n\u003cp>The woman \u003cstrong>who called me\u003c/strong> is Mina.\u003cbr>나에게 전화한 여자는 미나다.\u003c/p>\n\u003c/blockquote>\n\u003cp>전화한 주체가 \u003ccode>who\u003c/code>다.\u003c/p>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">관계절의 목적어\u003c/h3>\n\u003cblockquote>\n\u003cp>The woman \u003cstrong>whom I called\u003c/strong> is Mina.\u003cbr>내가 전화한 여자는 미나다.\u003c/p>\n\u003c/blockquote>\n\u003cp>전화한 주체는 \u003ccode>I\u003c/code>, 전화를 받은 대상은 \u003ccode>whom\u003c/code>이다.\u003c/p>\n\u003cp>격식 있는 문장에서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>who → 주격\u003c/strong>\u003cbr>\u003cstrong>whom → 목적격\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>을 구별한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. 회화에서는 목적격 \u003ccode>who\u003c/code>도 흔하다\u003c/h2>\n\u003cblockquote>\n\u003cp>The woman \u003cstrong>who I called\u003c/strong> is Mina.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 형태도 현대 영어, 특히 회화에서 자연스럽다.\u003c/p>\n\u003cp>제한적 관계절에서는 목적격을 생략할 수도 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>The woman \u003cstrong>I called\u003c/strong> is Mina.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서 목적어 자리라는 이유만으로 회화의 \u003ccode>who\u003c/code>를 모두 오류로 보지 않는다. \u003ccode>whom\u003c/code>은 특히 \u003cstrong>격식 있는 글과 전치사 바로 뒤\u003c/strong>에서 중요하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 전치사가 필요한 동사\u003c/h2>\n\u003cp>두 문장을 보자.\u003c/p>\n\u003cblockquote>\n\u003cp>I spoke \u003cstrong>to\u003c/strong> the woman.\u003cbr>나는 그 여자에게 말했다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>The woman is a doctor.\u003c/p>\n\u003c/blockquote>\n\u003cp>합치면:\u003c/p>\n\u003cblockquote>\n\u003cp>The woman \u003cstrong>who I spoke to\u003c/strong> is a doctor.\u003cbr>내가 이야기한 여자는 의사다.\u003c/p>\n\u003c/blockquote>\n\u003cp>관계절을 만들어도 원래 필요한 \u003ccode>to\u003c/code>는 남는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ The woman who I spoke is a doctor.\u003cbr>✅ The woman who I spoke \u003cstrong>to\u003c/strong> is a doctor.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 전치사를 앞으로 옮기기\u003c/h2>\n\u003cp>좀 더 격식 있는 형태:\u003c/p>\n\u003cblockquote>\n\u003cp>The woman \u003cstrong>to whom I spoke\u003c/strong> is a doctor.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻은 같다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>who I spoke to\u003c/strong> → 회화에서 자연스러움\u003cbr>\u003cstrong>to whom I spoke\u003c/strong> → 격식 있는 문어체\u003c/p>\n\u003c/blockquote>\n\u003cp>전치사를 앞으로 두면 사람에는 \u003cstrong>whom\u003c/strong>을 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ to \u003cstrong>whom\u003c/strong>\u003cbr>❌ to \u003cstrong>that\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>to who\u003c/code>는 격식 있는 표준 작문에서 피한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. 사물은 \u003ccode>전치사 + which\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>This is the house \u003cstrong>which I grew up in\u003c/strong>.\u003cbr>이것이 내가 자란 집이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>격식 있는 형태:\u003c/p>\n\u003cblockquote>\n\u003cp>This is the house \u003cstrong>in which I grew up\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>장소 관계부사를 쓰면:\u003c/p>\n\u003cblockquote>\n\u003cp>This is the house \u003cstrong>where I grew up\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 문맥에서 \u003ccode>where\u003c/code>는 \u003ccode>in which\u003c/code>에 해당한다.\u003c/p>\n\u003cp>하지만 장소 명사 뒤라고 무조건 \u003ccode>where\u003c/code>를 쓰는 것은 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>This is the house \u003cstrong>which I bought\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>bought\u003c/code>의 목적어인 집이므로 \u003ccode>which\u003c/code>다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. \u003ccode>that\u003c/code>과 생략의 제한\u003c/h2>\n\u003cp>전치사가 뒤에 있으면:\u003c/p>\n\u003cblockquote>\n\u003cp>the chair \u003cstrong>that I sat on\u003c/strong>\u003cbr>the chair \u003cstrong>I sat on\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 가능하다.\u003c/p>\n\u003cp>전치사를 앞으로 보내면:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ the chair \u003cstrong>on which I sat\u003c/strong>\u003cbr>❌ the chair \u003cstrong>on that I sat\u003c/strong>\u003cbr>❌ the chair \u003cstrong>on I sat\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>전치사 바로 뒤의 관계대명사는 that으로 바꾸거나 생략하지 않는다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. 원래 필요한 전치사를 선택한다\u003c/h2>\n\u003cblockquote>\n\u003cp>depend \u003cstrong>on\u003c/strong> someone\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>a person \u003cstrong>on whom I can depend\u003c/strong>\u003cbr>내가 의지할 수 있는 사람\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>work \u003cstrong>with\u003c/strong> someone\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>the colleague \u003cstrong>with whom I work\u003c/strong>\u003cbr>나와 함께 일하는 동료\u003c/p>\n\u003c/blockquote>\n\u003cp>무조건 \u003ccode>to whom / in which\u003c/code>를 쓰는 것이 아니다. \u003cstrong>원래 동사·표현의 관계\u003c/strong>를 먼저 확인한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. 계속적 관계절에서도\u003c/h2>\n\u003cblockquote>\n\u003cp>Mina, \u003cstrong>whom I met yesterday\u003c/strong>, is an architect.\u003cbr>미나는 건축가인데, 나는 어제 그녀를 만났다.\u003c/p>\n\u003c/blockquote>\n\u003cp>쉼표로 덧붙이는 관계절에서는 관계대명사를 생략하지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ Mina, \u003cstrong>whom I met yesterday\u003c/strong>, …\u003cbr>❌ Mina, \u003cstrong>I met yesterday\u003c/strong>, …\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>that\u003c/code>도 이 자리에는 쓰지 않는다. 회화의 목적격 \u003ccode>who\u003c/code>와 격식적인 \u003ccode>whom\u003c/code>은 모두 가능하지만, \u003cstrong>생략 가능 여부\u003c/strong>는 별개의 문제다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">9. \u003ccode>some of whom / both of which\u003c/code>\u003c/h2>\n\u003cp>집단의 일부를 설명할 수도 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>I met ten students, \u003cstrong>some of whom were from Korea\u003c/strong>.\u003cbr>학생 열 명을 만났는데, 그중 몇 명은 한국 출신이었다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She bought two books, \u003cstrong>both of which were expensive\u003c/strong>.\u003cbr>그녀는 책 두 권을 샀는데, 둘 다 비쌌다.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>\u003cp>사람들 → \u003ccode>whom\u003c/code>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>사물들 → \u003ccode>which\u003c/code>\u003c/p>\n\u003c/li>\n\u003c/ul>\n\u003cp>앞에서 배운 수량표현과 관계절이 결합한 구조다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">10. 전치사로 문장이 끝나도 괜찮다\u003c/h2>\n\u003cblockquote>\n\u003cp>Who are you talking \u003cstrong>to\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>That&#39;s the person I was talking \u003cstrong>about\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>현대 영어에서는 이런 형태가 자연스럽다. 전치사를 끝에 놓는 것을 전부 문법 오류라고 생각하지 않는다.\u003c/p>\n\u003cp>\u003cstrong>뜻은 같아도 격식의 정도가 다를 수 있다.\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">핵심\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>사람: to whom / with whom / for whom …\u003c/strong>\u003cbr>\u003cstrong>사물: in which / on which / about which …\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>전치사를 앞에 두는 격식형과 뒤에 두는 회화형을 모두 알아둔다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">연습\u003c/h2>\n\u003col>\n\u003cli>\u003cp>관계절의 주어 → the woman \u003cstrong>who / whom\u003c/strong> called me\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>격식형 → the person to \u003cstrong>whom / that\u003c/strong> I spoke\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>the house in \u003cstrong>which / that\u003c/strong> I grew up\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>the chair \u003cstrong>I sat on / on I sat\u003c/strong>\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Mina, \u003cstrong>whom I met yesterday / I met yesterday\u003c/strong>, is a doctor.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I met five students, two of \u003cstrong>whom / which\u003c/strong> were from Canada.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>산 집 → the house \u003cstrong>which I bought / where I bought\u003c/strong>\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>101단계 — 축약 관계절\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. who와 whom의 기본 역할","depth":2},{"id":"reading-2","label":"관계절의 주어","depth":3},{"id":"reading-3","label":"관계절의 목적어","depth":3},{"id":"reading-4","label":"2. 회화에서는 목적격 who도 흔하다","depth":2},{"id":"reading-5","label":"3. 전치사가 필요한 동사","depth":2},{"id":"reading-6","label":"4. 전치사를 앞으로 옮기기","depth":2},{"id":"reading-7","label":"5. 사물은 전치사 + which","depth":2},{"id":"reading-8","label":"6. that과 생략의 제한","depth":2},{"id":"reading-9","label":"7. 원래 필요한 전치사를 선택한다","depth":2},{"id":"reading-10","label":"8. 계속적 관계절에서도","depth":2},{"id":"reading-11","label":"9. some of whom / both of which","depth":2},{"id":"reading-12","label":"10. 전치사로 문장이 끝나도 괜찮다","depth":2},{"id":"reading-13","label":"핵심","depth":2},{"id":"reading-14","label":"연습","depth":2}],"origin":"notion","characters":3419,"aliases":{"structure":"concept","examples":"concept","contrast":"concept","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-12","topic-11":"reading-13","topic-12":"reading-14"}}]);
